insert into ponew values
(1, 1, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Laryngospasm at induction or emergence is first treated with:', '["100% oxygen with CPAP via a tight-fitting mask", "Removing all monitoring", "Increasing nitrous oxide", "Giving oral fluids and asking the patient to swallow"]'::jsonb, 0, 'If it persists, deepen anaesthesia or give a small dose of suxamethonium.', 'NAP 423 · General Anaesthesia I'),
(1, 2, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'In Nigeria and the UK, a medical oxygen cylinder is colour coded:', '["Blue body with blue shoulder", "Grey body with black shoulder", "Orange body with grey shoulder", "Black body with white shoulder"]'::jsonb, 3, 'N₂O is blue; Entonox is blue with blue and white shoulders.', 'NAP 423 · General Anaesthesia I'),
(1, 3, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Which factor REDUCES the MAC of volatile agents?', '["Young childhood", "Chronic alcohol abuse", "Hyperthermia", "Old age and pregnancy"]'::jsonb, 3, 'Opioids, hypothermia and sedatives also lower MAC.', 'NAP 423 · General Anaesthesia I'),
(1, 4, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient in the ICU develops urinary retention as a postoperative complication. Which intervention should the nurse implement to address this issue?', '["Insert a urinary catheter", "Encourage frequent ambulation", "Encourage the patient to drink plenty of fluids", "Administer diuretic medications"]'::jsonb, 0, 'Inserting a urinary catheter provides immediate bladder decompression when a patient cannot void postoperatively.', 'NAP 423 · General Anaesthesia I'),
(1, 5, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The Difficult Airway Society (DAS) guidelines'' Plan B after failed intubation is:', '["Insert a supraglottic airway to maintain oxygenation", "Proceed directly to surgery without any airway device in place", "Keep trying laryngoscopy many times", "Wake the patient without oxygen"]'::jsonb, 0, 'Plan C is face-mask ventilation; Plan D is front-of-neck access.', 'NAP 423 · General Anaesthesia I'),
(1, 6, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient is at risk for developing post-operative deep vein thrombosis (DVT). What nursing interventions can help prevent DVT in the post-operative period?', '["Monitor for signs and symptoms of DVT, such as swelling or pain in one leg", "Administer anticoagulant medications as prescribed", "Apply pneumatic compression devices to promote circulation", "Encourage early mobilization and activity"]'::jsonb, 1, 'Prescribed anticoagulant medication reduces clot formation risk in patients at risk for postoperative DVT.', 'NAP 423 · General Anaesthesia I'),
(1, 7, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Inadequate urine output (oligiuria) is defined as', '["Urine output of less than 0.5 ml/kg body weight /hour", "Urine output of 0.5 ml/kg body weight/hour", "Urine output of more than 0.5 ml/kg body weight/ hour", "Urine output of 5 ml/kg body weight /hour"]'::jsonb, 0, 'Oliguria in adults is generally defined as urine output less than 0.5 mL/kg/hour.', 'NAP 423 · General Anaesthesia I'),
(1, 8, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient develops a seroma following surgery. What nursing interventions are important for managing a seroma?', '["Apply pressure dressings over the seroma", "Keep the patient immobile to prevent fluid movement", "Perform needle aspiration to drain the seroma", "Administer diuretics to reduce fluid accumulation"]'::jsonb, 2, 'Needle aspiration drains a symptomatic seroma.', 'NAP 423 · General Anaesthesia I'),
(1, 9, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Intravenous regional anesthesia is more commonly used for operations of:', '["Lower limbs", "Neck surgeries", "Lower abdomen", "Upper limbs"]'::jsonb, 3, 'Intravenous regional anaesthesia (Bier''s block) is most commonly used for short procedures on the upper limb using a double tourniquet technique.', 'NAP 423 · General Anaesthesia I'),
(1, 10, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The definitive drug treatment for malignant hyperthermia is:', '["Naloxone", "Neostigmine", "Dantrolene", "Flumazenil"]'::jsonb, 2, 'Dantrolene works by inhibiting calcium release from the sarcoplasmic reticulum, directly reversing the hypermetabolic muscle crisis of malignant hyperthermia.', 'NAP 423 · General Anaesthesia I'),
(1, 11, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Propofol is commonly chosen for induction because it:', '["Gives smooth induction with quick, clear-headed recovery and less nausea", "Has no effect on breathing, so apnoea never occurs after induction", "Provides strong analgesia, so no opioid is needed during surgery", "Raises blood pressure and heart rate, so it is ideal in shocked patients"]'::jsonb, 0, 'Propofol causes hypotension and apnoea, so monitoring is essential. It is painful on injection, supports bacterial growth, and must be handled aseptically and discarded within the recommended time.', 'NAP 423 · General Anaesthesia I'),
(1, 12, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'How can kidney failure be managed in a patient postoperatively in the ICU?', '["Increasing fluid intake", "Administering diuretics", "Restricting protein intake", "Providing hemodialysis"]'::jsonb, 3, 'Haemodialysis provides renal replacement therapy to manage postoperative kidney failure when medical management is insufficient.', 'NAP 423 · General Anaesthesia I'),
(1, 13, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'What is a common cause of postoperative fever in ICU patients?', '["Infection", "Medication side effects", "Hypothermia", "Dehydration"]'::jsonb, 0, 'Infection is one of the most common causes of new fever in postoperative ICU patients and should be actively investigated.', 'NAP 423 · General Anaesthesia I'),
(1, 14, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient in the ICU develops a postoperative ileus. What intervention should the nurse implement to help alleviate the ileus?', '["Administer laxatives to promote bowel movements", "Encourage the patient to eat a high-fiber diet", "Insert a nasogastric tube for decompression", "Encourage the patient to perform deep breathing exercises"]'::jsonb, 2, 'Nasogastric decompression relieves gastric/bowel distension and reduces nausea and vomiting associated with postoperative ileus.', 'NAP 423 · General Anaesthesia I'),
(1, 15, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Which local anaesthetic belongs to the ester group?', '["Bupivacaine", "Procaine", "Mepivacaine", "Lignocaine"]'::jsonb, 1, 'Procaine is an ester. Amides have two "i"s in their name: lidocaine, bupivacaine, mepivacaine.', 'NAP 423 · General Anaesthesia I'),
(1, 16, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient develops a postoperative ileus. Which intervention is appropriate to help promote bowel function?', '["Providing a high-fiber diet", "Administering laxatives", "Restricting fluid intake", "Encouraging ambulation"]'::jsonb, 3, 'Ambulation stimulates bowel motility and helps resolve postoperative ileus.', 'NAP 423 · General Anaesthesia I'),
(1, 17, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The specific antidote for severe local anaesthetic systemic toxicity is:', '["IV 20% lipid emulsion", "IV dantrolene 2.5 mg/kg", "IV naloxone in boluses", "IV protamine sulphate"]'::jsonb, 0, 'Lipid emulsion acts as a ''lipid sink'' for fat-soluble local anaesthetics like bupivacaine. CPR may need to continue for a prolonged time.', 'NAP 423 · General Anaesthesia I'),
(1, 18, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Malignant hyperthermia is triggered by:', '["Nitrous oxide given on its own", "Local anaesthetics such as lidocaine", "Volatile agents and suxamethonium", "Propofol and fentanyl together"]'::jsonb, 2, 'MH is an inherited skeletal muscle disorder (RYR1 mutation). Triggers cause uncontrolled calcium release, producing rising end-tidal CO2, tachycardia, rigidity, hyperthermia and acidosis.', 'NAP 423 · General Anaesthesia I'),
(1, 19, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient in the ICU develops signs of sepsis postoperatively. What intervention should the nurse prioritize?', '["Administering pain medication", "Initiating intravenous fluids", "Providing oxygen therapy", "Checking vital signs frequently"]'::jsonb, 1, 'IV fluid resuscitation is a priority in postoperative sepsis to support perfusion, alongside prompt antibiotics and source control.', 'NAP 423 · General Anaesthesia I'),
(1, 20, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Awareness under general anaesthesia is most likely when:', '["The patient is paralysed but given too little anaesthetic", "The patient breathes spontaneously under deep anaesthesia", "The volatile agent concentration is high throughout surgery", "Only regional anaesthesia is used without any sedation"]'::jsonb, 0, 'Risk is increased in caesarean section, cardiac surgery, trauma and TIVA with disconnection. Depth-of-anaesthesia monitoring (e.g. BIS) may be used.', 'NAP 423 · General Anaesthesia I'),
(1, 21, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient is at risk for developing post-operative gastrointestinal complications. What nursing interventions can help prevent or manage gastrointestinal complications in the post- operative period?', '["Administer antiemetic medications as prescribed to control nausea and vomiting", "Advance the patient''s diet as tolerated to prevent ileus", "Encourage ambulation and early mobilization to promote GI motility", "Monitor bowel sounds and assess for abdominal distension or pain"]'::jsonb, 3, 'Monitoring bowel sounds and abdominal distension helps detect and guide management of postoperative gastrointestinal complications such as ileus.', 'NAP 423 · General Anaesthesia I'),
(1, 22, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Spinal (subarachnoid) anaesthesia involves injection of local anaesthetic into the:', '["Peripheral nerves of the brachial plexus in the arm", "Paravertebral muscles of the lower back on one side", "Epidural space at any level of the thoracic spine", "CSF below the end of the spinal cord, usually L3–L4"]'::jsonb, 3, 'In adults the cord usually ends at L1-L2, so spinal injection is made below this. CSF flow from the needle confirms placement. Onset is fast and the block is dense.', 'NAP 423 · General Anaesthesia I'),
(1, 23, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The recommended force for cricoid pressure in an awake patient before induction is about:', '["100 N throughout", "No force, just touch", "1 N throughout, as more force always causes oesophageal rupture", "10 N, increasing to 30 N after loss of consciousness"]'::jsonb, 3, 'Too much force can distort the airway.', 'NAP 423 · General Anaesthesia I'),
(1, 24, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Nasal prongs used to give oxygen at flow of', '["5-6 liter", "3-4 liter", "1-2 liter", "7-8 liter"]'::jsonb, 2, 'Standard nasal prongs/cannula are typically used at low flow rates of about 1-2 L/min for supplemental oxygen (limited by mucosal drying at higher flows).', 'NAP 423 · General Anaesthesia I'),
(1, 25, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'An ICU patient develops signs of delirium postoperatively. What nursing interventions are appropriate for managing delirium?', '["Ensuring a quiet environment", "Encouraging fluid intake", "Administering sedatives", "Limiting communication with the patient"]'::jsonb, 0, 'A calm, quiet, and appropriately oriented environment reduces sensory overload that can worsen postoperative delirium.', 'NAP 423 · General Anaesthesia I'),
(1, 26, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Endotracheal tube is best used for', '["Reducing secretions during regional anaesthesia", "Maintaining airway in anaesthetized patient", "Esophageal intubation", "Spinal anaesthesia"]'::jsonb, 1, 'An endotracheal tube secures and protects the airway, providing a definitive route for ventilation in an anaesthetised patient.', 'NAP 423 · General Anaesthesia I'),
(1, 27, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Minimum monitoring during general anaesthesia includes ECG, NIBP, pulse oximetry and:', '["Capnography and anaesthetic gas analysis", "Central venous pressure in every case", "Urine output and core temperature in every case", "Arterial line in every case"]'::jsonb, 0, 'A trained anaesthetist must be present throughout.', 'NAP 423 · General Anaesthesia I'),
(1, 28, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A postoperative patient is found to have signs of infection at the surgical site. What is the most appropriate action by the nurse?', '["Perform frequent dressing changes", "Administer prescribed antibiotics", "Apply ice to reduce swelling", "Keep the wound dry and uncovered"]'::jsonb, 1, 'Prescribed antibiotics treat the underlying infection at the surgical site.', 'NAP 423 · General Anaesthesia I'),
(1, 29, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A postoperative patient is experiencing paralytic ileus. What nursing intervention is appropriate for managing this complication?', '["Administering antiemetic medications", "Providing high-fiber diet", "Encouraging ambulation as tolerated", "Maintaining NPO status"]'::jsonb, 3, 'Keeping the patient NPO reduces gastric contents and vomiting risk while bowel motility is absent during paralytic ileus.', 'NAP 423 · General Anaesthesia I'),
(1, 30, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Methaemoglobinaemia is classically caused by which local anaesthetic?', '["Lignocaine", "Bupivacaine", "Procaine", "Prilocaine"]'::jsonb, 3, 'Prilocaine''s metabolite (o-toluidine) oxidises haemoglobin to methaemoglobin, especially at high doses.', 'NAP 423 · General Anaesthesia I'),
(1, 31, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The ''politics of health care'' in ICU management refers to:', '["Government salary scales for health workers only", "How power, resources and decisions are negotiated", "Nurses joining and campaigning for political parties", "Elections held to choose the ward manager"]'::jsonb, 1, 'Nurse managers must advocate effectively for staffing and resources.', 'NAP 423 · General Anaesthesia I'),
(1, 32, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Which postoperative complication can lead to atrial fibrillation and other cardiac issues?', '["Heart complications", "Delayed wound healing", "Stroke", "Pneumonia"]'::jsonb, 0, 'Postoperative cardiac complications, including new arrhythmias such as atrial fibrillation, are a recognised risk after surgery, particularly in patients with cardiac risk factors.', 'NAP 423 · General Anaesthesia I'),
(1, 33, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Suxamethonium should be used with caution in eye surgery for a penetrating eye injury because it:', '["Lasts for 24 hours", "Causes pupil constriction", "Raises intraocular pressure", "Lowers blood pressure to zero"]'::jsonb, 2, 'Weigh this against the need for rapid airway control.', 'NAP 423 · General Anaesthesia I'),
(1, 34, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A post-dural puncture headache is typically:', '["Constant and unaffected by any change in posture", "Worse on lying flat, eased by sitting up", "Associated with a high fever and rash in every case", "Worse on sitting or standing, eased by lying flat"]'::jsonb, 3, 'CSF leak lowers pressure, pulling on pain-sensitive structures. Treatment includes rest, fluids, analgesia, caffeine and, if persistent, an epidural blood patch.', 'NAP 423 · General Anaesthesia I'),
(1, 35, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'In which one of the following situations atropine is best indicated?', '["Hypertension", "Bradycardia", "Tachycardia", "Hypotension"]'::jsonb, 1, 'Atropine, an anticholinergic, blocks vagal effects on the heart and is the first-line drug for symptomatic bradycardia.', 'NAP 423 · General Anaesthesia I'),
(1, 36, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient in PACU is distressed and pulling at lines after waking. The nurse should first:', '["Leave them to settle alone with the curtains closed", "Give a large IV dose of benzodiazepine immediately to calm the patient", "Look for hypoxia, pain or a full bladder, and reorient", "Apply physical restraints to all four limbs at once"]'::jsonb, 2, 'Agitation may hide a serious cause.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 37, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Postoperative delirium in elderly patients is reduced by:', '["High doses of benzodiazepines given regularly at night", "Physical restraints on the bed to stop the patient falling", "Good pain control, glasses and hearing aids, and fewer sedatives", "Keeping them in a dark, noisy room for most of the day and night"]'::jsonb, 2, 'Delirium increases length of stay and mortality.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 38, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient with obstructive sleep apnoea in PACU should be nursed:', '["Alone in a side room to help them sleep", "Flat on the back with large doses of opioids", "Sitting up with oxygen, and CPAP if used at home", "Lying flat with no monitoring once they are awake and talking"]'::jsonb, 2, 'They are very sensitive to opioids and sedatives.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 39, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient aspirates acidic gastric contents during an emergency intubation. Within hours, the most likely picture is:', '["Wheeze, hypoxaemia and bilateral infiltrates (chemical pneumonitis)", "Lobar consolidation with a high fever within the first hour", "A normal chest X-ray with no respiratory symptoms at all", "A unilateral pleural effusion with a shift of the trachea"]'::jsonb, 0, 'Mendelson''s syndrome is chemical; bacterial pneumonia may follow later.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 40, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient in PACU is slow to wake 45 minutes after surgery. The nurse should first check:', '["Whether the family has arrived to visit, so they can help wake the patient", "The theatre list for the next case today", "Only the wound dressing for any bleeding", "Airway, breathing, SpO₂, glucose and temperature"]'::jsonb, 3, 'Causes include residual drugs, hypoglycaemia, hypothermia, hypercapnia and stroke.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 41, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'One of the fastest-acting inhalational agents is:', '["Isoflurane", "Sevoflurane", "Halothane", "Ether"]'::jsonb, 1, 'Sevoflurane has low blood–gas solubility, so induction and recovery are fast; it is also pleasant to breathe, making it good for inhalational induction.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 42, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'To reduce the risk of aspiration during induction of anaesthesia in an at-risk patient, the nurse/anaesthetist should ensure:', '["Adequate fasting time has been observed and rapid sequence induction is used if indicated", "The patient is positioned flat on their back with no head elevation regardless of risk", "The patient has recently eaten a full meal", "No airway equipment is prepared"]'::jsonb, 0, 'Adequate fasting and, where indicated, rapid sequence induction with cricoid pressure reduce aspiration risk in at-risk patients.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 43, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Anaesthetic deaths are reported and reviewed mainly to:', '["Delay the death certificate until the review is complete", "Avoid informing the family about the cause of the death", "Learn lessons and prevent deaths, with medico-legal accountability", "Identify and punish the anaesthetist responsible for the death"]'::jsonb, 2, 'Confidential enquiries identify system and individual factors.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 44, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Pain in a sedated patient who cannot speak can be assessed using:', '["The blood glucose level", "The patient''s appetite and fluid intake", "A behavioural pain scale", "The colour of the urine"]'::jsonb, 2, 'Examples are FLACC (children) and CPOT.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 45, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'When the surgeon asks for local anaesthetic, the scrub nurse should:', '["Use any open bottle from the previous case", "Show the ampoule and confirm the drug, strength and dose aloud", "Draw it up without checking, as the surgeon will check", "Ask the patient which drug they prefer and draw it up without checking"]'::jsonb, 1, 'All drugs on the sterile field must be labelled.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 46, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A post-operative patient who received a non-depolarising blocker is weak and anxious. Before giving more reversal, the anaesthetist may check:', '["Pupil size and reaction", "Blood alcohol level and liver function tests", "Train-of-four with a nerve stimulator", "Hourly urine output"]'::jsonb, 2, 'This guides whether further reversal is needed.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 47, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A nurse is administering anesthesia to a patient. The nurse knows that the main goal of anesthesia is to:', '["Cause the patient to feel every sensation of the procedure", "Increase the patient''s blood pressure", "Keep the patient awake during the procedure", "Provide a state of unconsciousness, muscle relaxation, and pain relief"]'::jsonb, 3, 'Anesthesia is a state of controlled, temporary loss of sensation or awareness. The goal is to provide a combination of unconsciousness, muscle relaxation, and pain relief so that the patient can undergo a surgical procedure without feeling or remembering it.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 48, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient s/p pneumonectomy has sudden SOB and hypotension. The nurse suspects:', '["Pulmonary embolism", "Pneumonia", "Myocardial infarction", "Tension pneumothorax"]'::jsonb, 0, 'Immobility and surgery increase PE risk.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 49, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient with hepatic encephalopathy needs nutrition. The current approach is:', '["Normal protein, with branched-chain amino acids if intolerant", "Complete protein restriction until the ammonia normalises", "A high-fat, carbohydrate-free diet to reduce ammonia", "Fasting until the encephalopathy has resolved fully"]'::jsonb, 0, 'Protein restriction worsens malnutrition; lactulose and rifaximin manage ammonia.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 50, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'An NSAID such as ibuprofen is avoided after surgery in a patient with:', '["A mild tension-type headache after the anaesthetic", "Acute kidney injury or active GI bleeding", "A clean, small surgical wound", "Normal kidney and liver function"]'::jsonb, 1, 'NSAIDs reduce renal blood flow and impair platelets.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 51, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Specimens for microbiological culture should be sent:', '["Frozen at −20 °C for one week", "Fresh in a sterile container without formalin", "Fixed straight away in 10% formalin, like a routine histology specimen", "Mixed with chlorhexidine first"]'::jsonb, 1, 'Formalin kills the organisms that need to be grown.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 52, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A PACU discharge criterion for pain is that pain is:', '["Absent completely in every single patient", "Not assessed if the patient is drowsy, as they cannot report it", "Controlled to an acceptable level, with a plan", "Severe but expected after major surgery"]'::jsonb, 2, 'Pain scores and analgesia given must be recorded.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 53, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Manual hyperinflation in ventilated patients aims to:', '["Re-expand collapsed alveoli and move secretions", "Increase the depth of patient sedation", "Replace the need for any suctioning", "Reduce oxygenation to rest the lungs"]'::jsonb, 0, 'It is avoided in patients with high PEEP needs or pneumothorax.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 54, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Theatre clinical waste contaminated with blood is placed in:', '["The rigid sharps box beside the table", "The infectious waste bag (usually yellow)", "The paper and plastic recycling bin near the theatre doors", "The black general (domestic) waste bag"]'::jsonb, 1, 'Sharps go in rigid puncture-proof containers.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 55, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient in PACU complains of chest pain with ST depression on the monitor. The nurse should:', '["Send the patient to the ward for observation and a review in the morning", "Give oxygen if needed, do a 12-lead ECG and call the doctor", "Give a laxative, as the pain may be from wind", "Wait to see whether the pain settles on its own"]'::jsonb, 1, 'Perioperative myocardial ischaemia is often silent.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 56, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'An alcohol-based skin preparation has been used. To prevent a surgical fire, the nurse should:', '["Drape immediately so that the alcohol fumes are trapped under the drapes", "Let the prep dry fully and fumes disperse before draping and diathermy", "Blot the prep with dry swabs and leave them on the skin under the drapes", "Increase the oxygen flow under the drapes to dilute the alcohol vapour"]'::jsonb, 1, 'The fire triangle is an ignition source (diathermy, laser), fuel (alcohol, drapes, gauze) and an oxidiser (oxygen, nitrous oxide). Pooled or wet alcohol and trapped vapour under drapes can ignite.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 57, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient s/p hip replacement has acute confusion. The nurse FIRST assesses for:', '["Pain", "Hypoxia", "Stroke", "Urinary retention"]'::jsonb, 1, 'Hypoxia is a reversible cause of delirium.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 58, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A nurse is caring for a patient who is post-anesthesia. The patient is experiencing nausea and vomiting. The nurse should:', '["Tell the patient to wait for the nausea to pass", "Encourage the patient to eat a large meal", "Administer an antiemetic as ordered", "Place the patient in a prone position"]'::jsonb, 2, 'Post-operative nausea and vomiting (PONV) is a common side effect of anesthesia. The nurse should administer an antiemetic as ordered to relieve the patient''s symptoms and prevent further complications like aspiration. The patient should not be encouraged to eat, and a prone position is not appropriate.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 59, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Reusable ventilator circuits and laryngoscope blades in ICU must undergo at least:', '["Wiping with a dry cloth after each use", "Rinsing with tap water between each patient", "Low-level disinfection with soap and water only", "Cleaning, then high-level disinfection or sterilisation"]'::jsonb, 3, 'Items touching mucous membranes are semi-critical (Spaulding). Single-use items must not be reprocessed.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 60, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'The minimum alveolar concentration (MAC) of a volatile agent is the concentration that:', '["Causes death in 50% of the patients exposed", "Is needed to produce full muscle relaxation", "Prevents movement to incision in 50% of patients", "Causes complete amnesia in every patient"]'::jsonb, 2, 'MAC is a measure of potency: the lower the MAC, the more potent the agent. It is reduced by age, opioids, hypothermia and pregnancy, and increased in children and alcoholics.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 61, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'In PACU, ''early warning score'' charts help nurses to:', '["Book theatre lists and order instruments for the next day", "Order surgical instruments for theatre", "Calculate drug doses for each patient", "Recognise deterioration early and escalate"]'::jsonb, 3, 'Scores combine vital signs into a single number.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 62, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A scrub nurse notices a hole in her glove during a case. She should:', '["Continue and change the glove at the very end", "Step back from the field and have the glove changed", "Put a second glove over the damaged glove and continue scrubbed in", "Cover the hole with a piece of adhesive tape"]'::jsonb, 1, 'The circulating nurse removes the outer glove; the gown cuff must not be contaminated.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 63, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A sickle cell patient''s Hb electrophoresis showing HbF elevated after hydroxyurea means:', '["The patient has beta thalassaemia major as well", "The patient is dehydrated and needs IV fluids", "The drug has failed and should be stopped now", "Hydroxyurea is raising fetal Hb, which reduces sickling"]'::jsonb, 3, 'Hydroxyurea reduces crises and acute chest syndrome.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 64, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient in PACU has an SpO₂ of 88% on room air but is breathing well. The nurse should first:', '["Remove the probe and record a value of 100%", "Ignore it, as an SpO₂ of 88% is normal after any general anaesthetic", "Give oxygen and check the airway and the probe", "Give a diuretic to clear fluid from the lungs"]'::jsonb, 2, 'Hypoxaemia after anaesthesia is common; find the cause.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 65, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A modified Allen''s test is performed before:', '["Central venous cannulation in the internal jugular", "Lumbar puncture for CSF sampling in meningitis", "Urinary catheterisation in men with retention", "Radial arterial puncture or arterial line insertion"]'::jsonb, 3, 'It checks ulnar collateral flow to the hand.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 66, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient in PACU after major abdominal surgery has a rising heart rate, falling BP and cool peripheries. The first step is:', '["Reduce the IV fluids to protect the heart from overload, and observe", "Look for bleeding, give oxygen and IV fluid, call the surgeon", "Discharge the patient to the ward for routine observations", "Give a sedative and wait to see if the vital signs settle"]'::jsonb, 1, 'Hypovolaemia from bleeding is the commonest cause.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 67, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Early mobilisation in ICU is safe when:', '["The patient''s SpO₂ is below 85% on high FiO₂", "The patient''s intracranial pressure is uncontrolled", "The patient is cardiovascularly and respiratorily stable", "The patient is on increasing doses of vasopressors"]'::jsonb, 2, 'Protocols guide progression from sitting to walking.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 68, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A suture described as ''2-0'' compared with ''4-0'' is:', '["Only used for skin", "The same thickness but absorbable", "Thinner", "Thicker"]'::jsonb, 3, 'The more zeros, the finer the suture; 6-0 is very fine, 1 is thick.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 69, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A postoperative ICU patient is at risk for developing pneumonia. What nursing interventions can help prevent pneumonia?', '["Providing supplemental oxygen", "Encouraging deep breathing exercises and coughing", "Administering antibiotics prophylactically", "Maintaining strict isolation precautions"]'::jsonb, 1, 'Deep breathing exercises and coughing help clear secretions and prevent atelectasis, reducing postoperative pneumonia risk.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 70, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A swab ticket or whiteboard count must show:', '["A total written at the end of the case from memory", "Only the items opened at the start of the case", "Every added item, recorded when it is added", "Only the needles used by the operating surgeon"]'::jsonb, 2, 'Additions must be counted when added.', 'NAP 414 · Nursing Anaesthesia Practice'),
(1, 71, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Ergonomics in the operating theatre refers to:', '["Fitting work and equipment to staff to reduce strain", "Administering drugs during anaesthesia", "Feeding patients after their operations", "Cleaning the theatre between surgical cases"]'::jsonb, 0, 'Adjusting table height, monitor positions and using anti-fatigue mats help.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 72, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Shift work and long hours in theatre can lead to:', '["Better quality sleep", "Fewer clinical mistakes", "Fatigue, errors and burnout", "Improved performance"]'::jsonb, 2, 'Adequate breaks and rotas reduce fatigue.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 73, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Neostigmine is given at the end of surgery to:', '["Reverse opioid respiratory depression by blocking mu receptors", "Reverse non-depolarising block by inhibiting acetylcholinesterase", "Treat malignant hyperthermia by reducing muscle calcium release", "Reverse benzodiazepine sedation by blocking GABA receptors"]'::jsonb, 1, 'Neostigmine increases acetylcholine at the neuromuscular junction. It is given with glycopyrrolate or atropine to block its muscarinic effects such as bradycardia and secretions.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 74, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Workplace stress among theatre nurses can be reduced by:', '["Blaming staff for errors", "Adequate staffing, support and clear communication", "Ignoring complaints", "Longer shifts without breaks"]'::jsonb, 1, 'Employee assistance programmes may also help.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 75, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Postoperatively, a patient develops urinary retention. What is the priority nursing action?', '["Initiating intermittent catheterization", "Providing a bedside commode", "Administering diuretics", "Encouraging decreased fluid intake"]'::jsonb, 0, 'Intermittent catheterisation empties the bladder as needed while preserving bladder tone better than an indwelling catheter for postoperative urinary retention.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 76, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Which postoperative complication is commonly associated with inadequate postoperative respiratory care?', '["Infection", "Bleeding", "Wound dehiscence", "Respiratory distress"]'::jsonb, 3, 'Inadequate postoperative respiratory care (poor deep breathing/coughing) predisposes to atelectasis and respiratory distress.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 77, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The ''hierarchy of controls'' for workplace hazards starts with:', '["Warning signs", "Personal protective equipment", "Training only", "Elimination of the hazard"]'::jsonb, 3, 'Then substitution, engineering controls, administrative controls and PPE.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 78, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Bullying and harassment at work should be:', '["Ignored", "Accepted as part of the job", "Handled by revenge", "Reported and dealt with according to policy"]'::jsonb, 3, 'It harms staff health and patient safety.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 79, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Which statement about etomidate is NOT true?', '["It inhibits cortisol synthesis", "It precipitates coronary insufficiency", "It is an intravenous anaesthetic", "It causes pain at the injection site"]'::jsonb, 1, 'Etomidate is cardiostable, which is why it is chosen in heart disease. It suppresses cortisol synthesis and causes injection pain and myoclonus.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 80, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The role of the anaesthetic nurse during induction includes:', '["Staying with the patient, assisting with the airway and applying cricoid when asked", "Positioning the surgical lights and the diathermy machine for the surgeon", "Leaving the room to collect instruments and sutures for the scrub nurse", "Opening the sterile packs onto the instrument trolley for the scrub team"]'::jsonb, 0, 'Induction is a high-risk time. The anaesthetic nurse provides reassurance, monitors, passes equipment, assists with difficult airways and helps secure the tube.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 81, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Poor functional capacity before surgery is suggested by inability to:', '["Sit up in bed unaided after a night''s sleep", "Climb two flights of stairs (less than 4 METs)", "Talk while sitting", "Walk across a room"]'::jsonb, 1, 'Poor exercise tolerance predicts more complications.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 82, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Following a needlestick injury, the first action is to:', '["Encourage bleeding, wash with soap and water, report", "Suck the wound to remove any infected blood", "Scrub the skin with undiluted bleach for 5 minutes", "Ignore it if the patient looks healthy"]'::jsonb, 0, 'Post-exposure prophylaxis for HIV should start within hours, ideally within 72 hours at the latest.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 83, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'In an epidural, the epidural space is identified by:', '["Free flow of clear cerebrospinal fluid from the hub of the needle", "Blood flashing back in the hub when the needle reaches the space", "Loss of resistance to saline or air as the needle passes the ligamentum flavum", "A click felt as the needle tip enters the bone of the vertebral body"]'::jsonb, 2, 'Unlike spinal anaesthesia, the dura is not punctured. CSF flow means accidental dural puncture; blood suggests a vessel, and the catheter is resited.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 84, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Night shift work increases the risk of:', '["Fatigue-related errors and sleep problems", "Improved diet", "Lower stress", "Better alertness"]'::jsonb, 0, 'Rest breaks and good rota planning help.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 85, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The chemical injury in Mendelson''s syndrome primarily results from which mechanism?', '["Acid damage to the alveolar-capillary membrane, causing leaky oedema", "Pulmonary arterial vasospasm triggered by the low pH", "Mechanical obstruction of the trachea by food particles alone", "Immune complex deposition in the pulmonary vascular bed"]'::jsonb, 0, 'Acidic gastric contents directly damage the alveolar-capillary membrane, increasing capillary permeability and causing a non-cardiogenic pulmonary oedema/ARDS-like picture.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 86, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A postoperative patient is found to have a large amount of fluid accumulation at the surgical site. What intervention should the nurse implement?', '["Perform sterile drainage of the seroma", "Apply compression bandages", "Encourage more intake of fluids", "Apply ice packs to reduce swelling"]'::jsonb, 0, 'Sterile needle drainage of a large, symptomatic seroma relieves the fluid collection while minimising infection risk.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 87, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Laser safety in theatre requires:', '["No special protection, because lasers are low-energy devices", "Open windows to let the laser beam escape safely from theatre", "Eye protection, warning signs and non-reflective instruments", "Shiny polished instruments to reflect the beam away from staff"]'::jsonb, 2, 'A laser safety officer oversees safe practice.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 88, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A patient in the ICU is receiving a continuous infusion of Propofol for sedation. The nurse should be aware that the patient is at risk for which of the following side effects?', '["Hyperthermia and tachycardia", "Hypotension and respiratory depression", "Seizures", "Hyperglycemia and hypertension"]'::jsonb, 1, 'Propofol is a potent sedative that has a strong cardiovascular effect. A common side effect is hypotension due to its vasodilation properties. It also has a powerful respiratory depressant effect, which is why patients receiving it often require mechanical ventilation.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 89, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Which neuromuscular blocker has the fastest onset of action?', '["Atracurium", "Succinylcholine", "Vecuronium", "Mivacurium"]'::jsonb, 1, 'Succinylcholine (suxamethonium) acts in 30–60 seconds, the fastest onset, which is why it is used for rapid-sequence induction.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 90, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Contact precautions for MRSA in ICU include:', '["Nursing in an open bay without isolation", "Gloves, apron or gown, own equipment, hand hygiene", "Airborne N95 masks only, without gloves", "No special precautions for MRSA patients"]'::jsonb, 1, 'Decolonisation may be used.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 91, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Dextrose is contraindicated in one of the following', '["Hypotension", "Hypertension", "Diabetics", "Pulmonary edema"]'::jsonb, 3, 'Dextrose-containing fluids can worsen fluid overload and are used cautiously in conditions like pulmonary oedema.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 92, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A patient on CRRT (dialysis) in ICU needs:', '["No nutrition at all until dialysis has stopped", "Very low protein to reduce the urea production", "More protein, as amino acids are lost in the effluent", "Potassium supplements added to every feed"]'::jsonb, 2, 'Protein needs may reach 1.5–2.5 g/kg/day.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 93, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The nurse is monitoring a sedated patient using the Bispectral Index (BIS) monitoring. The purpose of BIS monitoring is to:', '["Assess the patient''s muscle paralysis", "Monitor the patient''s blood pressure", "Measure the patient''s level of consciousness", "Assess the patient''s heart rate"]'::jsonb, 2, 'BIS monitoring uses a sensor on the patient''s forehead to measure brain activity. The BIS number provides a continuous assessment of the patient''s level of consciousness, helping to ensure the patient is not over- or under-sedated.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 94, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A patient is at risk for developing post-operative pressure injuries. What nursing interventions can help prevent pressure injuries in the post-operative period?', '["Implement a schedule for turning and repositioning the patient regularly", "Keep the skin clean and dry to prevent breakdown", "Assess bony prominences frequently for signs of redness or breakdown", "Use pressure-relieving devices such as cushions or mattresses"]'::jsonb, 0, 'A scheduled turning and repositioning programme is the core preventive measure against postoperative pressure injuries.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 95, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A recognised side effect of rapid high-dose fentanyl is:', '["Abdominal pain", "Hypertension", "Tachycardia", "Chest wall rigidity"]'::jsonb, 3, 'High-dose, rapid IV fentanyl can cause chest wall (truncal) rigidity that makes ventilation hard. It is reversed with naloxone or a muscle relaxant.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 96, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'What intervention is essential in preventing urinary retention postoperatively?', '["Increasing fluid intake", "Administering laxatives", "Reducing oral intake", "Encouraging early ambulation"]'::jsonb, 3, 'Early ambulation promotes normal bladder tone and reduces the risk of postoperative urinary retention.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 97, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The Mallampati classification is used before anaesthesia to:', '["Assess cardiac fitness from exercise tolerance", "Classify the severity of blood loss in trauma", "Grade the depth of anaesthesia during surgery", "Predict difficult intubation by viewing the oropharynx"]'::jsonb, 3, 'With the mouth open and tongue protruded, class I shows soft palate, fauces, uvula and pillars; class IV shows only the hard palate, suggesting difficult laryngoscopy.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 98, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A radiation dosimeter badge worn by theatre staff measures:', '["The radiation dose received over time", "Blood pressure", "Hearing", "Air temperature"]'::jsonb, 0, 'Wear it under the lead apron at chest or waist level.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 99, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Staff in theatre should be immunised against:', '["Typhoid fever", "Malaria", "Hepatitis B", "Rabies"]'::jsonb, 2, 'Hepatitis B vaccination and antibody response checks are standard for health workers.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 100, 'Anaesthesia Nursing Mock — Day 7 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The two-bag test on an anaesthetic machine checks:', '["The oxygen cylinder colour code and the pin-index system", "The steriliser pressure", "The breathing system''s valves and integrity with a test lung", "The patient''s blood group"]'::jsonb, 2, 'It is part of the routine machine check.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(2, 1, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Because of extensive skin loss, TENS patients are managed most similarly to which other critical care population?', '["Major burn patients", "Uncomplicated cellulitis patients", "Chronic wound outpatients", "Stable post-operative orthopedic patients"]'::jsonb, 0, 'The extensive skin loss, fluid shifts, and infection risk in TENS closely parallel major burn injury, so patients are often managed in a burn unit using burn-care principles.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 2, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'What is the injury to the alveoli caused by excessive pressure from the ventilator called?', '["Volume-trauma", "Biotrauma", "Atelecto-trauma", "Barotrauma"]'::jsonb, 3, 'Alveolar injury from excess ventilator pressure is barotrauma.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 3, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'In fetal circulation which of this is false?', '["The lungs are filled with fluid", "There are multiple shunts", "Two umbilical veins", "The placenta serves excretory purposes"]'::jsonb, 2, 'There is only ONE umbilical vein (carrying oxygenated blood), not two, making that statement false.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 4, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Which does NOT need to be excluded before testing for brain death?', '["Hypothermia", "Electrolyte imbalances", "Limb fractures", "Drug intoxication"]'::jsonb, 2, 'Before brainstem testing, exclude reversible causes: drugs and sedatives, hypothermia, and metabolic or electrolyte disturbances. Fractures do not affect the tests.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 5, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Which of the following is the initial analgesic drug of choice for a patient who is in severe pain, with a score of 9 out of 10, due to a fracture?', '["IV paracetamol", "Splint", "IV opiate", "Rectal NSAID"]'::jsonb, 2, 'IV opioid is the appropriate first-line choice for severe (9/10) acute fracture pain.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 6, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A 35-year-old woman from the Jos Plateau presents with an anterior neck swelling that moves with swallowing. She has no systemic symptoms. What is the most likely diagnosis?', '["Hashimoto''s thyroiditis", "Simple non-toxic goitre", "Thyrotoxicosis", "Follicular carcinoma"]'::jsonb, 1, 'Painless, moving-with-swallowing neck swelling with no systemic symptoms is the classic picture of a simple non-toxic goitre.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 7, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A nurse is assessing a patient with a known history of COPD. The nurse should be aware that the patient is at risk for Type II respiratory failure due to:', '["Chronic carbon dioxide retention", "An increase in gas exchange efficiency", "A decrease in lung compliance", "A hyperactive respiratory drive"]'::jsonb, 0, 'Many patients with COPD have chronically elevated PaCO₂ levels, making them susceptible to Type II respiratory failure. Their respiratory system has become less responsive to high CO₂ levels, and a further increase can lead to hypoventilation and acidosis.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 8, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'What do transport ventilators specifically cater to?', '["Delivery of smaller volumes and pressures", "Treatment of chronic conditions", "Non-invasive ventilation", "Transporting patients"]'::jsonb, 3, 'Transport ventilators are specifically designed and used for moving patients between locations.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 9, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'CSF from an EVD becomes cloudy, the patient febrile, and CSF glucose low. The nurse suspects:', '["Normal post-insertion change", "Subarachnoid haemorrhage", "Ventriculitis", "Over-drainage of CSF"]'::jsonb, 2, 'Send CSF for culture; strict asepsis when sampling reduces infection.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 10, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The presence of dysphagia suggests damage to cranial nerves:', '["III-VI", "IX-X", "V-VII", "VII-XI"]'::jsonb, 1, 'The glossopharyngeal (IX) and vagus (X) nerves supply the pharynx and larynx, so damage causes dysphagia.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 11, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'In a major haemorrhage protocol, tranexamic acid works best when given:', '["Within 3 hours of injury", "After bleeding has stopped", "Only to children", "Only after 24 hours"]'::jsonb, 0, 'Give blood products in balanced ratios (e.g. 1:1:1).', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 12, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The ''lethal triad'' in polytrauma refers to:', '["Hypothermia, acidosis and coagulopathy", "Anaemia, hypokalaemia and hyponatraemia", "Hypoxia, hypercapnia and hypotension", "Tachycardia, tachypnoea and fever"]'::jsonb, 0, 'Each worsens the others. Warming, early blood products and haemorrhage control break the cycle.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 13, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'In the mass causality post-earthquake in Balakot area of Pakistan in 2005.All the health volunteers from different health sector collectively categorizing patients based on the severity of injury with different color code. The color code Black represents;', '["High priority", "Deceased", "Minor injury", "Ambulatory"]'::jsonb, 1, 'Black designates deceased/expectant patients in mass-casualty triage.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 14, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A patient with stage 4 chronic kidney disease asks what type of diet they should follow. You explain the patient should follow a:', '["D Low protein, low sodium, low potassium, high phosphate diet", "A Low protein, low sodium, low potassium, low phosphate diet", "B High protein, low sodium, low potassium, high phosphate diet", "C Low protein, high sodium, high potassium, high phosphate diet"]'::jsonb, 1, 'CKD diet management favours low protein, low sodium, low potassium, and low phosphate intake.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 15, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A 19-year-old comes into the emergency department with acute asthma. His respiratory rate is 44 breaths/minute, and he appears to be in acute respiratory distress. Which of the following actions should be taken FIRST?', '["Take a full medication history.", "Provide emotional support to the client.", "Apply a cardiac monitor to the client.", "Give a bronchodilator by nebulizer."]'::jsonb, 3, 'In acute severe asthma, give a nebulised bronchodilator first. History can wait.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 16, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'In critical care, what is the primary role of a diuretic medication?', '["D) Reducing oxygen levels", "C) Promoting urine output", "B) Increasing heart rate", "A) Elevating blood pressure"]'::jsonb, 1, 'Diuretics work primarily by promoting urine output.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 17, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Torsades de pointes is treated first with:', '["IV digoxin 500 micrograms", "IV magnesium sulphate 2 g", "IV amiodarone 300 mg", "IV adenosine 6 mg"]'::jsonb, 1, 'Stop QT-prolonging drugs and correct potassium; pacing may be needed.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 18, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The patient has a risk of GI haemorrhage. For which of the critical symptoms should the patient be monitored?', '["Hematemesis and melena", "Hyperkalaemia and hypernatremia", "Metabolic acidosis and hypovolemia", "Decreasing haemoglobin levels"]'::jsonb, 0, 'Hematemesis and melena are the direct clinical signs of GI bleeding to monitor for.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 19, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'On the day of surgery, a patient''s regular β-blocker medication should generally be:', '["Stopped abruptly", "Doubled in dose", "Replaced with a diuretic", "Continued"]'::jsonb, 3, 'Suddenly stopping a β-blocker can cause dangerous rebound effects, so it is continued through the perioperative period.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 20, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Under normal conditions, intrapleural pressure is:', '["Positive during inhalation and negative during exhalation", "Always negative", "Negative during inhalation and positive during exhalation", "Always positive"]'::jsonb, 1, 'Normal intrapleural pressure is sub-atmospheric (negative) throughout quiet breathing, about −5 cmH2O at rest and more negative on inspiration. This keeps the lungs expanded.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 21, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A patient with carbon monoxide poisoning from smoke inhalation should be treated with:', '["Room air only", "IV antibiotics as the primary treatment", "Humidified 100% oxygen", "No oxygen therapy is needed"]'::jsonb, 2, 'CO binds haemoglobin far more strongly than oxygen — humidified 100% oxygen displaces CO from haemoglobin and is the mainstay treatment for CO poisoning.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 22, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A patient develops fever, tachycardia, tachypnoea, and hypotension not responding to an initial fluid bolus, with a known urinary tract infection. This presentation is most consistent with:', '["Simple dehydration", "Cardiogenic shock", "Anxiety attack", "Septic shock"]'::jsonb, 3, 'Fever with hypotension refractory to fluids in the setting of a known infection source is consistent with septic shock, requiring urgent sepsis bundle management.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 23, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Pulmonary oedema is the.........', '["Active movement of fluid across the capillary membrane into the alveoli", "Active movement of fluid across alveolar arterial membrane into the alveoli.", "Active movement of fluid across alveolar venous membrane into the alveoli", "Active movement of fluid across the heart to the lungs."]'::jsonb, 0, 'Pulmonary oedema is fluid actively moving across the capillary membrane into the alveoli.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 24, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'In accordance with American Heart Association resuscitation 2022 guide-line, the current concept of cardio-pulmonary resuscitation is:', '["HHHABCD", "ABCD", "ABCDHHH", "CABD"]'::jsonb, 3, 'Current AHA guidance emphasises compressions-first (CAB) sequencing in CPR.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 25, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'What is the preferred treatment for anaphylactic shock?', '["Epinephrine", "Place the patient in sitting position and administer oxygen", "Place a bag of ice on the area", "Prevent the infection from occurring through patient teaching"]'::jsonb, 0, 'Epinephrine is the first-line, life-saving treatment for anaphylaxis.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 26, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'After cardiac surgery, chest drain output suddenly stops while CVP rises and BP falls with pulsus paradoxus. The nurse suspects:', '["Hypovolaemia needing fluid restriction", "Recovery of normal clotting function", "Cardiac tamponade from clotted drains", "Right-sided pneumothorax only"]'::jsonb, 2, 'Milk or strip drains as per policy and call the surgeon at once; re-sternotomy may be needed.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 27, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A polytrauma patient develops confusion, hypoxia and a petechial rash over the axillae 48 hours after femoral fracture. The likely diagnosis is:', '["Septic shock from wound infection", "Fat embolism syndrome", "Pulmonary thromboembolism", "Transfusion-related lung injury"]'::jsonb, 1, 'Fat globules from long-bone marrow cause respiratory, neurological and skin features. Early fracture fixation reduces risk.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 28, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A nurse is assessing a patient with respiratory failure. The nurse notes that the patient''s respiratory rate is 35 breaths per minute. This is an example of:', '["Tachypnea", "Eupnea", "Apnea", "Bradypnea"]'::jsonb, 0, 'Tachypnea is an abnormally rapid respiratory rate, typically defined as more than 20 breaths per minute. The patient is breathing fast to compensate for the respiratory failure and try to improve gas exchange.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 29, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'There is surgical emphysema. This is?', '["Haemothorax", "Haemopneumothorax", "Pneumothorax", "Pleural effusion"]'::jsonb, 2, 'Surgical (subcutaneous) emphysema is associated with air leakage, as in pneumothorax.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 30, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Raised intracranial pressure above what value is a contraindication to physiotherapy?', '["ICP is not a consideration", ">5mmHg", ">50mmHg", ">20mmHg"]'::jsonb, 3, 'Physiotherapy manoeuvres can transiently raise ICP further, so it''s avoided once pressure is already significantly elevated.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 31, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The rapid shallow breathing index (RR/VT in litres) predicting weaning success is below:', '["300", "500", "105", "20"]'::jsonb, 2, 'Higher values suggest weaning failure.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 32, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Autocaval compression reduces .........to about 40%', '["Insomnia", "Apnoea", "Cardiac output", "Cardiac compression"]'::jsonb, 2, 'Aortocaval compression can reduce cardiac output by up to about 40% when a pregnant woman lies supine.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 33, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Which patient would require the least amount of, or no, heparin anticoagulation during hemodialysis?', '["A patient who is actively bleeding or recently had surgery", "A patient with a normal platelet count and coagulation studies", "A patient with no bleeding risk undergoing routine outpatient dialysis", "A patient with a well-functioning arteriovenous fistula"]'::jsonb, 0, 'In patients with active bleeding, recent surgery, or high bleeding risk, dialysis is often performed with minimal or no heparin, or regional citrate anticoagulation, to avoid worsening hemorrhage.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 34, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'What percentage of mechanically ventilated patients develop significant weakness?', '["75%", "25%", "5%", "100%"]'::jsonb, 1, 'A meaningful proportion, roughly a quarter, of ventilated patients go on to develop significant weakness.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 35, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'One of the tools used for monitoring a polytrauma patient is Glasgow Coma scale. The second parameter has a total of what score?', '["3", "15", "5", "6"]'::jsonb, 3, 'The GCS verbal response component has a maximum score of 5, but ''second parameter'' referring to eye opening or a specific listed subscale... commonly the verbal component max is 5; select based on standard subscale totals.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 36, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The intra-aortic balloon pump inflates during:', '["Only during cardiac arrest", "Both phases equally throughout", "Diastole, improving coronary flow", "Systole, increasing the afterload"]'::jsonb, 2, 'It deflates just before systole to reduce afterload.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 37, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'About endotracheal and tracheostomy tube insertion. Which one is not true', '["Malpositioning of the endotracheal tube (ETT) occurs in approximately 35% of endotracheal intubations.", "With the neck in neutral position, the ideal position of the tube tip is 5 to 7 cm above the carina;", "In 90% of patients, the carina projects between the fifth and seventh thoracic vertebrae on the portable radiograph", "The clinical assessment of tube location is frequently inaccurate, and a chest radiograph should be obtained immediately following intubation."]'::jsonb, 0, 'Malposition occurs in a substantial proportion (often cited around a third) of ETT placements, confirming the need for routine post-intubation X-ray.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 38, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Concerning the following investigation in DIC, which is not correct?', '["Fibrinogen is increased", "Platelet count is reduced", "Clotting factors are reduced", "Prothrombin time is prolonged"]'::jsonb, 0, 'Fibrinogen is decreased (consumed), not increased, in DIC — making that statement incorrect.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 39, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Abdominal compartment syndrome is defined as intra-abdominal (bladder) pressure above 20 mmHg with:', '["A soft abdomen on palpation", "A normal urine output", "New organ dysfunction", "Bowel sounds present"]'::jsonb, 2, 'Measure at end-expiration with the patient supine, zeroed at the mid-axillary line.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 40, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The recommended dose of neomycin in the management of PSE is:', '["1g every 6 hours", "500mg once weekly", "100mg every 6 hours", "10g once daily"]'::jsonb, 0, 'Neomycin reduces ammonia-producing gut bacteria; this is the standard dosing used in PSE management.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 41, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The door-to-balloon target for primary PCI in STEMI is within:', '["30 minutes of discharge", "90 minutes", "24 hours of the onset", "6 hours of arrival"]'::jsonb, 1, 'If PCI cannot be done within 120 minutes, thrombolysis within 30 minutes of arrival is preferred.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 42, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'On haemodynamic monitoring, a patient shows low cardiac output, high systemic vascular resistance, and a high pulmonary capillary wedge pressure. This pattern is most consistent with:', '["Hypovolaemic shock", "Distributive (septic) shock", "Cardiogenic shock", "Normal haemodynamics"]'::jsonb, 2, 'Cardiogenic shock classically shows low cardiac output with compensatory high SVR and elevated filling pressures (high wedge pressure) due to pump failure.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 43, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Which pathological reflex occurs in central paralysis (upper motor neuron lesion)?', '["Brown-Séquard", "Brudzinski", "Neri", "Babinski"]'::jsonb, 3, 'The Babinski reflex is the classic pathological reflex of upper motor neuron (central) paralysis.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 44, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The qSOFA criteria are respiratory rate ≥22/min, altered mentation and:', '["Urine output ≤0.5 mL/kg/h", "Temperature ≥38 °C", "Heart rate ≥90/min", "Systolic BP ≤100 mmHg"]'::jsonb, 3, 'Two or more positive criteria outside ICU signal higher risk of death.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 45, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Stress ulcer prophylaxis in ICU is clearly indicated in a patient who:', '["Eating a full diet after minor uncomplicated surgery", "Ventilated for over 48 hours, or with a coagulopathy", "Taking low-dose aspirin only, with no other risks", "With no bleeding risk factors and a short stay"]'::jsonb, 1, 'Other indications include shock, severe burns, head injury and high-dose steroids.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 46, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Artificial trans-fat is a type of fat that is added to some food products to improve taste, texture and extend their shelf life. However, trans fats can increase your risk of ............', '["Kidney diseases", "Heart diseases", "Lung diseases", "Diabetes"]'::jsonb, 1, 'Trans fats are strongly linked to increased heart disease risk.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 47, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Pendred syndrome is classically associated with goitre plus:', '["Congenital blindness", "Cardiac defects", "Renal failure", "Congenital deafness"]'::jsonb, 3, 'This inherited enzyme defect affects both the thyroid''s iodine handling and inner ear development.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 48, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Preload is best defined as:', '["The aortic diastolic pressure", "The intrinsic contractility of heart muscle", "The end-diastolic volume of the ventricle", "The wall tension the ventricle develops during ejection"]'::jsonb, 2, 'Preload is the ventricular end-diastolic volume (fibre stretch) before contraction.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 49, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Which of the following is not potentially life-threatening injuries', '["Hollow viscus injury", "Tracheobronchial injuries", "Pulmonary contusion", "Aortic injuries"]'::jsonb, 3, 'Aortic injury is actually classified as an immediately (not just potentially) life-threatening injury given its rapid lethality.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 50, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Which machine is known as the first negative-pressure machine used for long-term ventilation?', '["Iron Lung", "Ventilator", "Pulmonary Tank", "Respiratory Bladder"]'::jsonb, 0, 'The Iron Lung was the original negative-pressure ventilator for long-term use.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 51, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A 7-year-old client is brought to the E.R. He’s tachypneic and afebrile and has a respiratory rate of 36 breaths/minute and a nonproductive cough. He recently had a cold. From his history, the client may have which of the following?', '["Acute asthma", "Emphysema", "Bronchial pneumonia", "Chronic obstructive pulmonary disease (COPD)"]'::jsonb, 0, 'A tachypnoeic, afebrile child with a dry cough after a recent cold fits acute asthma.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 52, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Which class of medication reduces mortality in chronic heart failure with reduced ejection fraction by blocking the renin-angiotensin system?', '["ACE inhibitors", "Short-acting nitrates", "Calcium channel blockers (non-dihydropyridine)", "Loop diuretics alone"]'::jsonb, 0, 'ACE inhibitors block the renin-angiotensin-aldosterone system, reducing afterload and remodeling, and are proven to reduce mortality in HFrEF.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 53, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A 55 year old male patient is admitted with a massive GI bleed. The patient is at risk for what type of acute kidney injury?', '["Intra-renal", "Post-renal", "Intrinsic renal", "Pre-renal"]'::jsonb, 3, 'Massive GI bleeding causing hypovolaemia is a classic pre-renal cause of AKI.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 54, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'About cardiac pacemaker', '["Cardiac pacemakers can be inserted by trans venous only", "Most often the trans venous approach is used", "When viewed on a chest radiograph, the pacemaker lead should terminate in the right ventricular apex", "The right internal jugular and the left subclavian veins are often preferred"]'::jsonb, 0, 'Pacemakers can also be inserted via epicardial/surgical approaches, not only transvenously — making that absolute statement incorrect.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 55, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Which arrhythmia is treated with synchronised cardioversion rather than defibrillation?', '["Ventricular fibrillation", "Asystole", "Atrial fibrillation", "Pulseless VT"]'::jsonb, 2, 'Elective cardioversion suits AF, atrial flutter, SVT and VT with a pulse. Pulseless VT and VF need unsynchronised defibrillation.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 56, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Each kidney receives blood from..................', '["Renal artery", "Afferent arteriole", "Inter lobular veins", "Renal vein"]'::jsonb, 0, 'Each kidney receives its blood supply from the renal artery.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 57, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Volume of air inspired or expired by a person from lungs in a minute:', '["Inspiratory Volume", "Expiratory Volume", "Minute Volume", "Tidal Volume"]'::jsonb, 2, 'Total air moved per minute is minute volume (tidal volume × respiratory rate).', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 58, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Hypophosphataemia in ICU may cause:', '["Hypercalcaemia with kidney stones and polyuria", "Severe hypertension with headache and blurring", "Respiratory muscle weakness and failed weaning", "Tetany only, without any muscle weakness"]'::jsonb, 2, 'Common in refeeding and DKA treatment.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 59, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'What name is given to the mechanical contraction of the heart?', '["Depolarisation", "Diastole", "Repolarisation", "Systole"]'::jsonb, 3, 'Systole is the mechanical contraction phase of the heart. Depolarisation is the electrical event that triggers it.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 60, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A diabetic patient on iv normal saline was discovered to have random blood sugar RBS of 2.5mmol/l, which of this action will you take as critical care Nurse?', '["Change the fluid to glucose containing fluid", "Change to ringers'' lactate", "Stop the fluid and wait for the Physician", "Send for the physician and wait for his order"]'::jsonb, 0, 'A dangerously low RBS of 2.5mmol/L on normal saline needs correction with a glucose-containing fluid.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 61, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'By Sepsis-3, septic shock is sepsis needing vasopressors to keep MAP ≥65 mmHg and:', '["A temperature above 38 °C for over an hour", "A positive blood culture result from the lab", "A white cell count above 12 × 10⁹/L on admission", "Lactate above 2 mmol/L despite adequate fluids"]'::jsonb, 3, 'Hospital mortality of septic shock is above 40%.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 62, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A patient requires mechanical ventilation for airway protection due to a decreased level of consciousness (GCS 6) after a head injury. This is an example of which broad indication for ventilation?', '["Primary oxygenation failure", "Primary ventilatory (CO2) failure", "Inability to protect the airway", "Post-anesthesia recovery only"]'::jsonb, 2, 'A markedly depressed level of consciousness compromises airway reflexes, making inability to protect the airway a key indication for intubation and ventilation.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 63, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Hypothermia in trauma (accidental hypothermia) is considered severe below:', '["28 °C", "32 °C", "35 °C", "34 °C"]'::jsonb, 0, 'Severe hypothermia risks VF; patients should be handled gently and rewarmed actively.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 64, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Head elevation of 30–45° is recommended in inhalational injury management to:', '["Improve hearing", "Reduce airway oedema", "Prevent pressure sores", "Improve appetite"]'::jsonb, 1, 'Elevating the head helps reduce swelling around the airway, lowering the risk of obstruction.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 65, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'You have a patient that might have a urinary tract infection (UTI). Which statement by the patient suggests that a UTI is likely?', '["“I go hours without the urge to pee.”", "“My pee smells sweet.”", "“It burns when I pee.”", "“I pee a lot.”"]'::jsonb, 2, 'Dysuria (burning on urination) is a classic UTI symptom.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 66, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'When the demand of self-care is greater than individual''s capacity or ability to meet the patient''s need in the critical care settings, this lead to care being compromised, this indicates:', '["Self-compromise", "Self-insistencies", "Self-incompetency", "Self-care deficit"]'::jsonb, 3, 'When self-care needs exceed the patient''s ability to meet them, this is termed a self-care deficit.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 67, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Low potassium level is termed _____', '["Hyper-potassium syndrome", "Hyperkalemia", "Hypokalemia", "Hypo-potassiumaemia"]'::jsonb, 2, 'Low potassium is hypokalaemia.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 68, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The antidote for paracetamol (acetaminophen) overdose is:', '["IV flumazenil", "IV N-acetylcysteine", "IV naloxone", "IV protamine sulfate"]'::jsonb, 1, 'It is most effective within 8 hours. Use the treatment nomogram and monitor liver function and INR.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 69, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'About central venous catheters select the wrong answer', '["Placement into the right ventricle may result in arrhythmias secondary to irritation of the endocardium or interventricular septum", "Positioning of the catheter tip within the right atrium is common and may result in cardiac perforation and tamponade.", "Appropriate catheter position must be verified radiographically", "Malposition has been described in up to 80% of CVCs."]'::jsonb, 3, 'Reported CVC malposition rates are much lower than 80% — that figure is incorrect.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 70, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Intra-abdominal hypertension is:', '["When IAP is consistently \\> 5 mmHg without organ dysfunction", "When IAP is consistently \\>12 mmHg with organ dysfunction", "When IAP is consistently \\<12 mmHg with organ dysfunction", "When IAP is \\>12 mmHg without organ dysfunction"]'::jsonb, 3, 'Intra-abdominal hypertension is defined as sustained IAP >12mmHg WITHOUT necessarily needing organ dysfunction to be present.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 71, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Polycythaemia is best classified as:', '["Acute and chronic", "Primary and secondary", "Benign and malignant", "Morbid and premorbid"]'::jsonb, 1, 'Polycythaemia is primary (polycythaemia vera, a marrow disorder) or secondary (raised EPO from hypoxia, tumours). Relative polycythaemia is due to low plasma volume.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 72, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'The most common anticoagulant used in blood bank donor bags is:', '["Heparin", "EDTA", "Double oxalate", "Tri-sodium citrate"]'::jsonb, 3, 'Citrate (tri-sodium citrate, as in CPDA-1) is the blood-bank anticoagulant. It binds calcium.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 73, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Glycosylated haemoglobin (HbA1c) reflects average blood glucose control over approximately:', '["The past 5 years", "The past 24 hours", "A single fasting measurement", "The past 2–3 months"]'::jsonb, 3, 'HbA1c reflects the percentage of haemoglobin glycosylated over the roughly 120-day lifespan of red blood cells, giving an average picture of glycaemic control over about 2–3 months.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 74, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'The modified Allen''s test is positive (normal) when:', '["Colour returns within 5–15 seconds after ulnar release", "The radial pulse disappears on release", "The patient feels pain in the fingers", "The hand stays pale for more than 30 seconds"]'::jsonb, 0, 'A delayed return suggests poor ulnar collateral flow.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 75, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'For a patient with multiple febrile reactions, the nurse requests:', '["Leukocyte-reduced blood", "Volume-reduced platelets", "Irradiated blood", "Washed RBCs"]'::jsonb, 0, 'Leukocyte reduction prevents febrile non-hemolytic reactions.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 76, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A bone marrow condition in which all formed elements of the blood are simultaneously reduced is:', '["Iron-deficiency anaemia", "Aplastic anaemia", "Haemolytic anaemia", "Thalassaemia"]'::jsonb, 1, 'Aplastic anaemia is bone marrow failure with pancytopenia, a reduction in all three cell lines at once.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 77, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A patient with iron overload from transfusions receives:', '["Vitamin K", "FFP", "Deferoxamine", "Protamine"]'::jsonb, 2, 'Deferoxamine chelates excess iron.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 78, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Platelets should not be given through:', '["A peripheral cannula", "A used blood giving set", "A platelet or new standard giving set", "A central line"]'::jsonb, 1, 'Use a fresh set to avoid platelet loss.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 79, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Sterilisation, as distinct from disinfection, is defined as a process that:', '["Only reduces the number of organisms, without eliminating any", "Kills most pathogens but not bacterial spores", "Kills ALL microorganisms, including bacterial spores", "Is only relevant to skin antisepsis"]'::jsonb, 2, 'Sterilisation (e.g. via autoclaving) destroys all microorganisms including resistant bacterial spores, unlike disinfection which reduces most pathogens but may not eliminate spores.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 80, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'DIC laboratory findings include:', '["Normal clotting times with a low D-dimer level", "Low platelets and fibrinogen, long PT/APTT, high D-dimer", "Isolated high haemoglobin with normal platelets", "High platelets and high fibrinogen with short clotting times"]'::jsonb, 1, 'Treat the cause and replace components.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 81, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Which person should be deferred if the event happened within the previous 24 hours?', '["A person who ate breakfast", "A person who drank alcohol", "A person who slept 8 hours", "A person who had a cholesterol check"]'::jsonb, 1, 'Anyone who has drunk alcohol in the previous 24 hours should not donate blood.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 82, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Spontaneous bleeding risk significantly increases when the platelet count falls below approximately:', '["100,000/microL", "250,000/microL", "150,000/microL", "10,000–20,000/microL"]'::jsonb, 3, 'Spontaneous bleeding risk rises sharply when platelets drop to roughly 10,000–20,000/microL, though risk begins increasing well before this level, especially with additional bleeding risk factors.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 83, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A blood film showing fragmented red cells (schistocytes) suggests:', '["Iron deficiency from chronic bleeding", "A normal blood film in a healthy adult", "Vitamin B12 deficiency with large cells", "Microangiopathic haemolysis (DIC, TTP)"]'::jsonb, 3, 'TTP needs urgent plasma exchange.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 84, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Both clotting and bleeding occur in DIC because:', '["Excess thrombin uses up clotting factors faster than they can be replaced", "The intrinsic pathway releases excess clotting factors", "Only clotting occurs in DIC", "Bleeding uses up clotting factors faster than they are replaced"]'::jsonb, 0, 'Excess thrombin generation forms clots throughout the microcirculation and uses up clotting factors and platelets faster than they can be replaced, so bleeding follows.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 85, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'The normal haemoglobin range for an adult male is approximately:', '["20–24 g/dL", "13.5–17.5 g/dL", "6–8 g/dL", "2–4 g/dL"]'::jsonb, 1, 'Normal adult male haemoglobin is roughly 13.5–17.5 g/dL, somewhat higher than the typical adult female range of about 12–15.5 g/dL.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 86, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A patient on high-dose corticosteroids is at risk for:', '["Hypoglycemia", "Hypothyroidism", "Adrenal suppression", "Hyperkalemia"]'::jsonb, 2, 'Chronic steroids suppress the HPA axis, requiring stress-dose coverage.', 'NAP 421 · Applied Pharmacology II'),
(2, 87, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Poisoning management in the ICU may include gastric lavage, which is most effective when performed:', '["Only in infants", "Within about 1 hour of ingestion (up to 2–4 hours in some cases), and never in corrosive poisoning", "More than 24 hours after ingestion", "At any time regardless of the substance ingested"]'::jsonb, 2, 'Gastric lavage is most useful shortly after ingestion (roughly within 1–4 hours) and is contraindicated in corrosive/caustic poisoning due to perforation risk.', 'NAP 421 · Applied Pharmacology II'),
(2, 88, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A patient taking ibuprofen 400 mg twice daily for chronic back pain develops leg oedema. This is most likely caused by:', '["An increase in plasma proteins", "A decrease in renal function", "An increased glomerular filtration rate", "A low creatinine level"]'::jsonb, 1, 'NSAIDs block renal prostaglandins, reducing renal blood flow and GFR and causing sodium and water retention and oedema.', 'NAP 421 · Applied Pharmacology II'),
(2, 89, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'The context-sensitive half-time of an IV anaesthetic describes:', '["The time for plasma level to halve after stopping an infusion of a given length", "The time to reach peak effect after a single bolus dose", "The time taken for the drug to be fully excreted in the urine", "The half-life of the drug when given by mouth"]'::jsonb, 0, 'It rises with infusion duration for drugs like fentanyl, but stays short for remifentanil.', 'NAP 421 · Applied Pharmacology II'),
(2, 90, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Noradrenaline has leaked from a peripheral IV into the tissues. The specific treatment is:', '["Applying heat and massaging the area", "Local infiltration with phentolamine", "Local injection of more noradrenaline", "Giving IV furosemide"]'::jsonb, 1, 'Stop the infusion, leave the cannula to aspirate, elevate the limb and give through a central line.', 'NAP 421 · Applied Pharmacology II'),
(2, 91, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A patient on a propofol infusion develops metabolic acidosis and rhabdomyolysis. The nurse suspects:', '["Serotonin syndrome", "Anaphylaxis", "Malignant hyperthermia", "Propofol infusion syndrome"]'::jsonb, 3, 'PRIS is a rare but fatal complication of propofol, characterized by lactic acidosis, rhabdomyolysis, and cardiac failure.', 'NAP 421 · Applied Pharmacology II'),
(2, 92, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A patient on long-term diuretic therapy develops muscle weakness, cramping, and an irregular pulse. The nurse should suspect an electrolyte disturbance, most likely:', '["Hypercalcaemia", "Hypernatraemia", "Hypokalaemia", "Hyperglycaemia"]'::jsonb, 2, 'Muscle weakness, cramping and arrhythmia in a patient on diuretics (especially loop/thiazide) are classic signs of hypokalaemia, a common diuretic side effect.', 'NAP 421 · Applied Pharmacology II'),
(2, 93, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A 53-year-old patient who is receiving ibuprofen 400 mg twice a day, for chronic, low back pain develops lower-extremity oedema. The pain management nurse suspects that the oedema is caused by:', '["A low creatinine level.", "An increase in glomerular filtration rate", "An increase in plasma proteins.", "A decrease in renal function"]'::jsonb, 3, 'NSAIDs can reduce renal blood flow/function, causing fluid retention and oedema.', 'NAP 421 · Applied Pharmacology II'),
(2, 94, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'NPH insulin is given at 07:30. When will it reach its peak effect?', '["11:30–13:30", "15:30–21:30", "13:30–19:30", "17:30–23:30"]'::jsonb, 2, 'NPH (intermediate) insulin peaks about 6–12 hours after injection, so a 07:30 dose peaks around 13:30–19:30.', 'NAP 421 · Applied Pharmacology II'),
(2, 95, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A patient presents with pinpoint pupils, respiratory rate of 6 breaths/min, decreased level of consciousness, and bradycardia. Which toxidrome does this most likely represent?', '["Anticholinergic toxidrome", "Opioid toxidrome", "Cholinergic toxidrome", "Sympathomimetic toxidrome"]'::jsonb, 1, 'Miosis (pinpoint pupils), respiratory depression, and CNS depression are the classic triad of opioid toxicity.', 'NAP 421 · Applied Pharmacology II'),
(2, 96, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'If manual bagging of a patient with a suspected blocked ETT meets high resistance and chest rise is absent despite confirmed tube position, the appropriate next step is:', '["Wait for the physician without further action", "Increase bagging force and continue indefinitely", "Administer a bronchodilator via metered-dose inhaler through the tube", "Prepare to remove/change the endotracheal tube emergently"]'::jsonb, 3, 'When bagging shows high resistance and no chest rise despite a tube confirmed to be positioned correctly, the tube itself is likely obstructed and should be emergently removed/changed rather than forcing further ventilation attempts.', 'NAP 421 · Applied Pharmacology II'),
(2, 97, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Furosemide, a loop diuretic, most commonly causes:', '["Hypercalcaemia and stones", "Hypokalaemia and dehydration", "Hyperkalaemia and oedema", "Weight gain and fluid retention"]'::jsonb, 1, 'Electrolytes, fluid balance and blood pressure are monitored. High IV doses given fast can cause ototoxicity.', 'NAP 421 · Applied Pharmacology II'),
(2, 98, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Which one of the following drug is administered every 3-5 minutes of CPR?', '["Epinephrine", "Vasopressin", "Atropine", "Amiodarone"]'::jsonb, 0, 'Epinephrine is re-dosed every 3-5 minutes during resuscitation.', 'NAP 421 · Applied Pharmacology II'),
(2, 99, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Compared with the other agents listed, which is most likely to cause direct, dose-dependent myocardial contractile depression rather than predominantly vasodilation?', '["Desflurane", "Halothane", "Sevoflurane at low concentrations", "Isoflurane"]'::jsonb, 1, 'Halothane depresses myocardial contractility more directly than isoflurane, desflurane, or sevoflurane, which cause relatively more vasodilation with better-preserved cardiac output at equivalent MAC.', 'NAP 421 · Applied Pharmacology II'),
(2, 100, 'Anaesthesia Nursing Mock — Day 7 Afternoon (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Which inhalational anaesthetic agent has the lowest blood-gas partition coefficient among the following, resulting in the most rapid induction and emergence?', '["Desflurane", "Isoflurane", "Sevoflurane", "Halothane"]'::jsonb, 0, 'Desflurane has a blood:gas partition coefficient of about 0.42, the lowest of the common volatile agents, giving it the fastest onset and offset of action.', 'NAP 421 · Applied Pharmacology II'),
(3, 1, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Which drug is contraindicated for controlling postpartum bleeding in a woman with eclampsia?', '["Oxytocin", "Misoprostol", "Carboprost", "Ergometrine"]'::jsonb, 3, 'Ergometrine causes vasoconstriction that can dangerously raise already-high blood pressure.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 2, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Post-caesarean section, early mobilisation is encouraged mainly to:', '["Reduce the need for breastfeeding", "Reduce DVT and chest complications", "Reduce lochia flow from the uterus", "Reduce wound pain in the first day"]'::jsonb, 1, 'Pregnancy and the post-partum period increase VTE risk; LMWH and stockings may be prescribed.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 3, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Gastric outlet obstruction from pyloric stenosis in an adult typically causes:', '["Jaundice and dark urine with pale stools and itching of the skin", "Projectile vomiting of food and hypochloraemic alkalosis", "Bloody diarrhoea and high fever with abdominal cramps", "Constipation with no vomiting and normal electrolytes"]'::jsonb, 1, 'A succussion splash may be heard.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 4, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'The ''4 Ts'' of postpartum haemorrhage are:', '["Tone, Trauma, Tissue, Thrombin", "Temperature, Time, Tachycardia, Tension", "Tests, Transfusion, Treatment, Transfer", "Tachycardia, Tachypnoea, Temperature, Thirst"]'::jsonb, 0, 'Uterine atony (tone) is the commonest cause.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 5, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A double-volume exchange transfusion in a neonate uses about:', '["300–350 mL/kg of blood", "80–90 mL/kg of blood", "40–60 mL/kg of blood", "160–180 mL/kg of blood"]'::jsonb, 3, 'Neonatal blood volume is 80–90 mL/kg; double volume replaces about 85% of the baby''s red cells.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 6, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Physiological jaundice differs from pathological jaundice because physiological jaundice:', '["Requires exchange transfusion in all cases", "Appears after 24 hours and resolves by 2 weeks", "Is associated with a conjugated bilirubin rise", "Appears within the first 24 hours"]'::jsonb, 1, 'Jaundice in the first 24 hours is always pathological.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 7, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'The respiratory rate considered fast breathing in a child aged 2–12 months is:', '["80 breaths/min or more", "30 breaths/min or more", "50 breaths/min or more", "20 breaths/min or more"]'::jsonb, 2, 'For 1–5 years: 40 or more; under 2 months: 60 or more.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 8, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'In bacterial meningitis, dexamethasone is given before or with the first antibiotic dose to reduce:', '["Hearing loss and neurological complications", "The need for maintenance IV fluids", "The total duration of the antibiotic course", "Fever only, with no effect on outcome"]'::jsonb, 0, 'It is most effective in Haemophilus influenzae and pneumococcal meningitis.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 9, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A percutaneous nephrolithotomy patient develops breathlessness after surgery. The nurse should suspect:', '["Constipation from the opioid analgesia given after surgery", "Pleural injury such as pneumothorax or hydrothorax", "Normal recovery", "Urinary tract infection"]'::jsonb, 1, 'Upper pole access can injure the pleura.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 10, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A child with a severe asthma attack not responding to salbutamol may need:', '["Oral sedation and discharge home", "Oral antibiotics and nothing else", "Strict fluid restriction for 24 hours", "IV magnesium sulphate and oxygen"]'::jsonb, 3, 'Aminophylline and ventilation may follow.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 11, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'The most dangerous organism causing puerperal sepsis is:', '["Staphylococcus epidermidis from the skin", "Group A Streptococcus (S. pyogenes)", "Lactobacillus species from the vagina", "Candida albicans after antibiotics"]'::jsonb, 1, 'It can cause rapid toxic shock; early IV antibiotics and source control are vital.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 12, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A gravida 9 presents with history of amenorrhea for 7 weeks, PV bleeding, lower abdominal pain, and fainting twice yesterday. Her diagnosis is likely:', '["Implantation bleeding", "Abortion", "Placenta Previa", "Ectopic pregnancy"]'::jsonb, 3, 'Amenorrhoea, bleeding, abdominal pain, and fainting in a multigravida strongly suggest ectopic pregnancy.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 13, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Before an emergency laparotomy, the patient is kept nil by mouth mainly to:', '["Prevent dehydration before surgery", "Lower the blood pressure", "Improve wound healing later", "Reduce the risk of aspiration"]'::jsonb, 3, 'An NG tube may also be passed to empty the stomach.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 14, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A urine sample for culture from a catheter should be taken:', '["From the drainage bag", "From the sampling port using aseptic technique", "From the drainage bag tap after it has been emptied", "By disconnecting the bag"]'::jsonb, 1, 'Bag urine is contaminated.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 15, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A category 1 caesarean section (immediate threat to life of mother or baby) should ideally deliver the baby within:', '["The next elective list, within 24 hours", "30 minutes of the decision", "24 hours of the decision", "4 hours of the decision"]'::jsonb, 1, 'Category 2 targets within 75 minutes.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 16, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'This condition describe a birth defect where some nerve cells are missing in the large intestine:', '["Birth stenosis", "Hirsh sprung disease", "Appendicitis", "Pyloric Hirsh sprung"]'::jsonb, 1, 'Absent nerve cells (ganglion cells) in the large intestine defines Hirschsprung''s disease.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 17, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Carboprost (15-methyl PGF2α) should be avoided in:', '["Diabetes", "Asthma", "Anaemia", "Hypertension"]'::jsonb, 1, 'It causes bronchospasm.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 18, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Acute lymphoblastic leukaemia treatment in ICU may cause:', '["Neutropenic sepsis and tumour lysis syndrome", "Immediate iron overload needing chelation", "Hypercoagulability with deep vein thrombosis", "Polycythaemia with hyperviscosity and stroke"]'::jsonb, 0, 'Prophylactic allopurinol or rasburicase and hydration prevent TLS.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 19, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Neonatal hypoglycaemia is treated with an IV bolus of:', '["10 mL/kg of 50% dextrose", "1 mL/kg of 5% dextrose", "2 mL/kg of 10% dextrose", "5 mL/kg of 25% dextrose"]'::jsonb, 2, 'Higher concentrations are hypertonic and damage veins.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 20, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Oxygen saturation targets of about 91–95% in preterm infants help prevent:', '["Umbilical cord infection", "Neonatal hypoglycaemia", "Retinopathy of prematurity", "Physiological neonatal jaundice"]'::jsonb, 2, 'Both too much and too little oxygen cause harm.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 21, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Bartholin''s cyst recurrence is reduced by:', '["Marsupialisation", "Simple needle aspiration only", "Ice packs", "Antibiotic cream alone"]'::jsonb, 0, 'This creates a permanent opening for drainage.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 22, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Corticosteroids are given to a mother whose delivery is planned before 37 weeks to:', '["Keep the mother calm", "Help the baby''s lungs mature", "Prepare the cervix for delivery", "Prevent maternal fits"]'::jsonb, 1, 'Antenatal corticosteroids (dexamethasone/betamethasone) before 34–37 weeks speed fetal lung maturation and reduce RDS.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 23, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Rh incompatibility is of particular clinical concern in pregnancy when:', '["Both parents are Rh-negative", "The mother is blood type O", "An Rh-negative mother carries an Rh-positive fetus", "An Rh-positive mother carries an Rh-negative fetus"]'::jsonb, 2, 'An Rh-negative mother sensitised to Rh-positive fetal blood (often from a prior pregnancy) can develop antibodies that cross the placenta and cause haemolytic disease in a subsequent Rh-positive fetus.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 24, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Volkmann''s ischaemic contracture is a complication of:', '["Untreated forearm compartment syndrome", "A skull fracture with a small haematoma", "A simple ankle sprain in a crepe bandage", "Femoral neck fracture after hemiarthroplasty"]'::jsonb, 0, 'Brachial artery injury or swelling in supracondylar fractures in children can lead to muscle necrosis and claw-hand contracture.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 25, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'After a vasectomy, the man is told that:', '["Contraception must continue until semen tests confirm no sperm", "The operation is easily reversed", "He is sterile immediately and no other contraception is ever needed", "He cannot have sex for a year"]'::jsonb, 0, 'Sperm remain in the tubes for some weeks.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 26, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A woman in the third trimester with sudden breathlessness, chest pain and tachycardia most likely has:', '["Heartburn", "Mild asthma", "Pulmonary embolism", "Normal pregnancy breathlessness"]'::jsonb, 2, 'Pregnancy is a hypercoagulable state; LMWH is the treatment.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 27, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'In neonatal resuscitation, after drying and stimulating, the next assessment is:', '["Non-invasive blood pressure", "Breathing and heart rate", "Blood glucose level", "Core temperature only"]'::jsonb, 1, 'If apnoeic or HR below 100, start inflation breaths and ventilation.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 28, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A common urinary catheter size for an adult is:', '["4–6 Ch", "24–30 Ch for routine drainage", "40 Ch", "12–14 Ch (French)"]'::jsonb, 3, 'Larger three-way catheters (e.g. 20–22 Ch) are used for haematuria and irrigation.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 29, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Medical treatment of an unruptured ectopic pregnancy with stable vital signs and low hCG may use:', '["Misoprostol alone", "Oxytocin", "Methotrexate", "Magnesium sulfate"]'::jsonb, 2, 'Serial hCG levels are followed until negative.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 30, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'The initial analgesic of choice for a patient with severe fracture pain (9/10) is:', '["IV paracetamol", "Oral codeine", "Rectal NSAID", "IV opiate"]'::jsonb, 3, 'Severe acute pain (9/10) needs a titrated IV opioid. Splinting and paracetamol are adjuncts.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 31, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Vaginal bleeding after 28 weeks of pregnancy which is sudden in onset, painless, causeless and recurrent is known as.', '["Abruption placentae", "Vasa praevia", "Placenta praevia", "Abortion"]'::jsonb, 2, 'Sudden, painless, recurrent bleeding after 28 weeks is the classic description of placenta praevia.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 32, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Room air is used at the start of term newborn resuscitation because:', '["Oxygen is never needed in newborns", "It increases the heart rate faster", "Excess oxygen may harm the newborn", "It is cheaper than oxygen"]'::jsonb, 2, 'Oxygen is titrated to target pre-ductal SpO₂ on the right hand.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 33, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Bilious vomiting in a newborn requires an urgent:', '["Stool test for reducing sugars and pH", "Trial of a change of formula milk for 24 hours", "A course of oral antibiotics and review", "Upper GI contrast study to exclude malrotation"]'::jsonb, 3, 'Volvulus can cause gangrene of the whole midgut within hours.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 34, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Unexplained fractures in an infant of different ages on X-ray should raise concern of:', '["Vitamin C excess", "Non-accidental injury (child abuse)", "Simple falls only", "Normal growth and development in infancy"]'::jsonb, 1, 'Follow safeguarding procedures.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 35, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'An inguinal hernia in a child is usually due to:', '["Weak abdominal muscles from age", "A patent processus vaginalis", "Heavy lifting", "Obesity"]'::jsonb, 1, 'Infant hernias are repaired promptly because of a high risk of incarceration.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 36, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'What proportion of maternal deaths are estimated to occur in the postpartum period?', '["5%", "40%", "100%", "75%"]'::jsonb, 1, 'This substantial proportion highlights why vigilant postpartum monitoring is so important, not just monitoring during labour and delivery.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 37, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A child weighing 18 kg is prescribed an antibiotic at 10 mg/kg/day divided every 8 hours. How many milligrams should be given per dose?', '["90 mg", "30 mg", "60 mg", "180 mg"]'::jsonb, 2, 'Total daily dose = 18 kg x 10 mg/kg = 180 mg/day. Divided every 8 hours = 3 doses/day, so 180/3 = 60 mg/dose.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 38, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Normal intracranial pressure in an adult is generally considered to be:', '["0–15 mmHg", "Above 25 mmHg at baseline", "30–40 mmHg", "50–60 mmHg"]'::jsonb, 0, 'Normal ICP in adults is typically cited as roughly 0–15mmHg; sustained pressures above about 20mmHg are generally considered pathological and require intervention.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 39, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A full-thickness skin graft is preferred for the face because it:', '["Can cover much larger areas than a split graft", "Is quicker and easier to take than other grafts", "Has better colour match and less contraction", "Heals faster at the donor site than a split graft"]'::jsonb, 2, 'Common donor sites are behind the ear and above the clavicle.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 40, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A ''curtain'' coming down over the vision suggests:', '["Retinal detachment", "Allergic conjunctivitis", "Dry eye", "Cataract"]'::jsonb, 0, 'Urgent referral is needed.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 41, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Acute sinusitis complications that need urgent care include:', '["Mild nasal stuffiness", "Sneezing and a mild runny nose only", "Orbital cellulitis and meningitis", "Watery eyes only"]'::jsonb, 2, 'Eye swelling with reduced vision is an emergency.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 42, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'After craniotomy, a patient''s urine output rises to 300 mL/h with high serum sodium. The nurse suspects:', '["Heart failure", "Diabetes insipidus", "SIADH", "Acute kidney injury"]'::jsonb, 1, 'Report it; desmopressin may be needed.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 43, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Oxygen given under eye drapes during surgery with cautery increases the risk of:', '["Hypertension", "Hypothermia", "Infection", "Fire"]'::jsonb, 3, 'Use the lowest oxygen needed and allow it to clear.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 44, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Cataract is defined as:', '["Inflammation of the conjunctiva", "Detachment of the retina", "Opacity of the lens of the eye", "Raised pressure inside the eye"]'::jsonb, 2, 'Cataract causes gradual painless loss of vision. Surgery replaces the lens with an intraocular lens implant.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 45, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Amniotic fluid embolism is definitively confirmed by:', '["Autopsy", "Routine blood test", "Ultrasound", "Clinical symptoms alone"]'::jsonb, 0, 'There is no reliable test to confirm AFE while the patient is alive — diagnosis is only confirmed at autopsy.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 46, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A woman who has never been pregnant before is described as:', '["Nulligravida", "Multigravida", "Primigravida", "Primipara"]'::jsonb, 0, 'Nulligravida: a woman who has never been pregnant. Primigravida: pregnant for the first time.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 47, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Chronic subdural haematoma in the elderly is often drained by:', '["Lumbar puncture", "Craniectomy in all cases", "Burr holes", "Medication only"]'::jsonb, 2, 'Recurrence is possible; monitor for confusion.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 48, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A free fibula flap is commonly used to reconstruct the:', '["Mandible", "Ear (pinna)", "Eyelid", "Nose tip"]'::jsonb, 0, 'It provides bone with its own blood supply.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 49, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Refer to Q#19, the patient had undergone through craniotomy. Bleeding was notified on CT scan after one week of surgery which is known as;', '["Secondary Hemorrhage", "Reactionary Hemorrhage", "Primary Hemorrhage", "Venous Hemorrhage"]'::jsonb, 0, 'Bleeding appearing a week after surgery is delayed — secondary haemorrhage, usually from infection.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 50, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Before ENT surgery under general anaesthesia, the throat pack must be:', '["Documented and removed before extubation", "Not counted, because it is not a swab", "Removed by the patient once fully awake", "Left in place to absorb blood after surgery"]'::jsonb, 0, 'Retained throat packs can cause airway obstruction. They are included in the count.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 51, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Open reduction and internal fixation of the mandible commonly uses:', '["External skin traction", "Titanium miniplates and screws", "Elastic bandages only", "Plaster of Paris around the jaw"]'::jsonb, 1, 'They allow earlier jaw movement than wiring alone.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 52, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A patient with a new spinal cord injury and SBP 80 with HR 45 is likely in:', '["Hypovolaemic shock only", "Cardiogenic shock", "Neurogenic shock", "Septic shock"]'::jsonb, 2, 'Treat with fluids, vasopressors and atropine if needed.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 53, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'The two drugs used together to manage the hypermetabolic response in burns are:', '["Adrenaline and atropine", "Furosemide and spironolactone", "Propranolol and oxandrolone", "Insulin and glucagon"]'::jsonb, 2, 'A beta-blocker (propranolol) reduces the hyperdynamic cardiovascular response, while an anabolic steroid (oxandrolone) helps counter the muscle-wasting hypermetabolic state.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 54, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Thoracostomy differs from thoracotomy in that it is:', '["A small opening for placing a chest drain", "Only used for cardiac surgery", "A large incision for major intrathoracic surgery", "Identical to thoracotomy"]'::jsonb, 0, 'Thoracostomy is a much smaller procedure aimed specifically at inserting a drainage tube, not full surgical access.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 55, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Temporary epicardial pacing wires after heart surgery are used to:', '["Measure the arterial blood pressure", "Measure the oxygen saturation", "Drain blood from the pericardium", "Treat bradycardia or heart block"]'::jsonb, 3, 'The wires are removed before discharge; the patient is monitored for tamponade afterwards.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 56, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Chest tube drainage exceeding approximately 200–300mL per hour after coronary artery bypass surgery should prompt concern for:', '["Resolution of the surgical procedure", "Normal expected postoperative drainage", "Postoperative haemorrhage requiring urgent evaluation", "Chest tube malfunction only, with no clinical significance"]'::jsonb, 2, 'Chest tube output consistently exceeding roughly 200–300mL/hour (or specific institutional thresholds) after cardiac surgery raises concern for significant postoperative bleeding and may require surgical re-exploration.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 57, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Timolol eye drops should be used with caution in patients with:', '["Hearing loss", "Skin rash", "High blood sugar only", "Asthma or bradycardia"]'::jsonb, 3, 'Beta-blocker drops can be absorbed systemically.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 58, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Burkitt''s lymphoma in African children typically presents as:', '["A pathological fracture of the femur", "A painless cystic swelling in the neck", "A fast-growing jaw or abdominal mass", "A slow-growing pigmented skin lesion"]'::jsonb, 2, 'It is associated with Epstein-Barr virus and malaria. It responds well to chemotherapy.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 59, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Diabetes insipidus after pituitary surgery presents with:', '["Large volumes of dilute urine with a rising sodium", "Low serum sodium with confusion and seizures", "Concentrated dark urine with a falling serum sodium", "Very low urine output with fluid overload and oedema"]'::jsonb, 0, 'It is due to lack of ADH. Fluid balance and serum sodium are monitored; desmopressin may be given.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 60, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'The incubation period of Lassa fever is about:', '["2 months", "1–2 hours", "1 year", "6–21 days"]'::jsonb, 3, 'Early symptoms are non-specific: fever, sore throat and malaise.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 61, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'The main airway risk after major maxillofacial surgery is:', '["Tension pneumothorax from the central line inserted in theatre", "Bronchospasm from the volatile agent used during the operation", "Laryngeal oedema from an allergy to the antibiotic given", "Swelling, bleeding and secretions blocking the upper airway"]'::jsonb, 3, 'Patients may have a nasopharyngeal airway or tracheostomy. Suction, head elevation and close observation are essential.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 62, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Subarachnoid haemorrhage presents with:', '["Sudden ''thunderclap'' headache, neck stiffness and photophobia", "Painless loss of vision in one eye with no headache at all", "Gradual mild headache that is relieved by rest and paracetamol", "Fever, productive cough and pleuritic chest pain for a week"]'::jsonb, 0, 'It is most often due to ruptured berry aneurysm. Vasospasm is prevented with nimodipine.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 63, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Lung resection called pneumonectomy refers to removal of:', '["The trachea", "One lobe of a lung", "A wedge of lung tissue", "An entire lung"]'::jsonb, 3, 'After pneumonectomy, a chest drain is often not connected to suction to avoid mediastinal shift.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 64, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A patient with endophthalmitis needs:', '["Steroid cream on the eyelids only", "Urgent intravitreal antibiotics", "Eye drops only after a week", "Eye exercises"]'::jsonb, 1, 'Vision can be lost within hours.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 65, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'The basal metabolic rate (BMR) in a major burns patient can increase by:', '["No change", "500–600%", "10–20%", "100–200%"]'::jsonb, 3, 'The body''s energy demands roughly double or triple after a major burn, driving the hypermetabolic state that must be matched with adequate nutrition.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 66, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Fracture of the zygoma may cause:', '["Hearing loss only on the side of the injury", "Painless haematuria from associated kidney injury", "Loss of taste only on the front of the tongue", "A flat cheek, cheek numbness and double vision"]'::jsonb, 3, 'The infraorbital nerve may be damaged, and the orbital floor may be involved, causing eye problems.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 67, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A patient with a head injury has a Glasgow Coma Scale score of 10. This is classified as which severity of traumatic brain injury?', '["Mild", "Moderate", "Severe", "Vegetative state"]'::jsonb, 1, 'A GCS of 9-12 is classified as moderate traumatic brain injury, between mild (13-15) and severe (3-8).', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 68, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Myringoplasty is:', '["Repair of a perforated eardrum", "Removal of the tonsils", "Insertion of ventilation tubes", "Removal of the stapes bone"]'::jsonb, 0, 'The graft is commonly taken from temporalis fascia.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 69, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A patient with a skull fracture and bruising behind the ear has:', '["Battle''s sign of a basal skull fracture", "Grey Turner''s sign of retroperitoneal bleeding", "Cullen''s sign of acute pancreatitis", "Trousseau''s sign of hypocalcaemia"]'::jsonb, 0, 'Periorbital bruising (raccoon eyes) is another sign of basal skull fracture.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 70, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'The most common benign salivary gland tumour is:', '["Ameloblastoma", "Warthin''s tumour only", "Mucoepidermoid carcinoma", "Pleomorphic adenoma"]'::jsonb, 3, 'It usually occurs in the parotid gland.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 71, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient develops post-operative respiratory complications. What nursing interventions can help manage respiratory complications in the post-operative period?', '["Encourage deep breathing exercises and use of incentive spirometry", "Encourage smoking to help open up the airways", "Administer sedatives to keep the patient calm and reduce respiratory effort", "Keep the patient in a supine position at all times"]'::jsonb, 0, 'Deep breathing exercises and incentive spirometry help re-expand alveoli and prevent atelectasis after surgery.', 'NAP 432 · General Anaesthesia II'),
(3, 72, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Muscle pains (myalgia) the day after surgery are a known side effect of:', '["Suxamethonium", "Fentanyl", "Propofol given at induction", "Rocuronium"]'::jsonb, 0, 'Fasciculations from depolarisation cause the myalgia.', 'NAP 432 · General Anaesthesia II'),
(3, 73, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A common oral endotracheal tube size for an adult woman is:', '["4.0–4.5 mm internal diameter", "10.0–10.5 mm internal diameter", "7.0–7.5 mm internal diameter", "5.0 mm internal diameter"]'::jsonb, 2, 'Adult men usually take 8.0–8.5 mm.', 'NAP 432 · General Anaesthesia II'),
(3, 74, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Dexamethasone used for PONV prophylaxis is best given:', '["At discharge from hospital", "At induction of anaesthesia", "Only after the patient vomits", "The week before surgery"]'::jsonb, 1, 'It works slowly; check glucose in diabetics.', 'NAP 432 · General Anaesthesia II'),
(3, 75, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient in the ICU is at risk for developing delirium. What nursing interventions can help prevent delirium?', '["Limiting visitation from family members", "Keeping the environment quiet and calm", "Administering sedatives regularly", "Restraining the patient to prevent wandering"]'::jsonb, 1, 'A calm, quiet environment with orientation cues helps prevent and manage ICU delirium.', 'NAP 432 · General Anaesthesia II'),
(3, 76, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Regarding depolarizing muscle relaxant metabolism which is correct', '["Metabolized in the liver", "Metabolized by acetyl choline esterase", "Under go Hoffman elimination", "Hydrolyzed in plasma psedocholine esterase"]'::jsonb, 1, 'Depolarising muscle relaxants such as succinylcholine are hydrolysed by plasma (pseudo)cholinesterase, not by acetylcholinesterase (a different enzyme found at the neuromuscular junction).', 'NAP 432 · General Anaesthesia II'),
(3, 77, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A key difference between spinal and epidural anaesthesia is that spinal anaesthesia:', '["Cannot cause hypotension", "Is always preferred for short procedures under 10 minutes", "Is injected into the subarachnoid space with faster onset", "Uses a much larger drug volume"]'::jsonb, 2, 'Spinal anaesthesia delivers a small volume of local anaesthetic directly into the CSF-filled subarachnoid space, producing rapid, dense block, unlike the larger-volume epidural space injection used for epidurals.', 'NAP 432 · General Anaesthesia II'),
(3, 78, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Before transferring a patient from PACU to the ward, the nurse should ensure:', '["That the anaesthetist has gone home and the surgeon has seen the patient", "Only that the bed is clean and that the porter has arrived to collect the patient", "Full handover, with observations, drugs given and post-op orders documented", "That all IV lines, drains and catheters have been removed before the transfer"]'::jsonb, 2, 'Safe transfer includes a fully charted record of observations, analgesia, antiemetics, fluids and any events.', 'NAP 432 · General Anaesthesia II'),
(3, 79, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'After tonsillectomy, frequent swallowing in a sleeping child in PACU suggests:', '["Bleeding from the tonsil bed", "Hunger after fasting", "Pain from the throat only", "Normal recovery after surgery"]'::jsonb, 0, 'Look in the mouth, check pulse and call the surgeon.', 'NAP 432 · General Anaesthesia II'),
(3, 80, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A bispectral index (BIS) value of 40–60 during general anaesthesia indicates:', '["The patient is fully awake", "Too deep anaesthesia needing reversal", "Brain death", "An adequate depth of anaesthesia"]'::jsonb, 3, 'It may help reduce awareness in TIVA.', 'NAP 432 · General Anaesthesia II'),
(3, 81, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Before discharge from PACU, wound drains and dressings should be:', '["Ignored if the patient is awake and alert", "Removed in all patients before leaving, so the ward has less work", "Checked, with the drainage volume recorded", "Covered with extra tape and not checked"]'::jsonb, 2, 'Sudden high drain output should be reported.', 'NAP 432 · General Anaesthesia II'),
(3, 82, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient is at risk for developing post-operative nausea and vomiting. What nursing interventions can help prevent or manage post-operative nausea and vomiting?', '["Keep the patient NPO (nothing by mouth) to prevent nausea", "Administer antiemetic medications as ordered", "Encourage the patient to eat a large meal immediately after surgery", "Provide small, frequent meals and clear liquids as tolerated"]'::jsonb, 1, 'Antiemetic medication is the primary intervention to prevent and manage postoperative nausea and vomiting.', 'NAP 432 · General Anaesthesia II'),
(3, 83, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The ASA physical status classification for a patient with well-controlled hypertension and no other disease is:', '["ASA III", "ASA I", "ASA IV", "ASA II"]'::jsonb, 3, 'ASA I is a normal healthy patient; ASA II has mild systemic disease without functional limitation (controlled hypertension, mild asthma); ASA III has severe systemic disease; ASA IV has severe disease that is a constant threat to life.', 'NAP 432 · General Anaesthesia II'),
(3, 84, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Which of the following postoperative complications involves the abnormal accumulation of fluid at the surgical site?', '["Adhesion formation", "Urinary retention", "Paralytic ileus", "Seroma"]'::jsonb, 3, 'A seroma is a localised collection of serous fluid at the surgical site.', 'NAP 432 · General Anaesthesia II'),
(3, 85, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Laryngeal mask air way is not used in one of the following cases', '["Patient with short period operation", "Patient with operation in face", "Patient with operation in lower part of the body", "Patient with full stomach"]'::jsonb, 3, 'A laryngeal mask airway does not protect against aspiration and is avoided in patients with a full stomach or high aspiration risk.', 'NAP 432 · General Anaesthesia II'),
(3, 86, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient is receiving Midazolam for sedation. The nurse knows that Midazolam is a:', '["Benzodiazepine", "Neuromuscular blocking agent", "Beta-blocker", "Opioid analgesic"]'::jsonb, 0, 'Midazolam is a benzodiazepine, which is a class of drugs that acts on the central nervous system to produce sedation and amnesia. It is commonly used for short-term sedation and anxiolysis.', 'NAP 432 · General Anaesthesia II'),
(3, 87, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A post-thyroidectomy patient in PACU develops a rapidly enlarging neck swelling and stridor. The first action is to:', '["Wait for the surgeon''s next ward round to review the wound", "Apply a tight pressure bandage around the patient''s neck to stop the bleeding", "Give oral fluids to help the patient swallow more easily", "Call for help and open the sutures to release the haematoma"]'::jsonb, 3, 'Clip or suture removers should be at the bedside.', 'NAP 432 · General Anaesthesia II'),
(3, 88, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient in PACU suddenly cannot speak and has new arm weakness. The nurse suspects:', '["Stroke; call for urgent medical review", "Low urine output from fasting", "Normal effect of the anaesthetic", "Pain from the surgical wound causing the patient to refuse to talk"]'::jsonb, 0, 'Note the time of onset; urgent imaging may be needed.', 'NAP 432 · General Anaesthesia II'),
(3, 89, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Which agent is NOT used to produce induced (controlled) hypotension during surgery?', '["Hydralazine", "Esmolol", "Mephentermine", "Sodium nitroprusside"]'::jsonb, 2, 'Esmolol, hydralazine and sodium nitroprusside lower BP. Mephentermine is a sympathomimetic vasopressor that raises it.', 'NAP 432 · General Anaesthesia II'),
(3, 90, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient in PACU after a regional block has a numb, weak arm. The nurse should:', '["Start vigorous arm exercises at once to restore the feeling", "Tell the patient that the numbness is likely to be permanent", "Apply a hot water bottle to the arm to speed up the return of sensation", "Protect the limb in a sling and explain sensation will return"]'::jsonb, 3, 'Numb limbs are at risk of injury.', 'NAP 432 · General Anaesthesia II'),
(3, 91, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'In 70 kg patient one unit of platelet concentrate should increase platelet count:', '["More than 20000 / mm3", "2000 - 5000 / mm3", "5000 - 10000 / mm3", "10000 - 20000 / mm3"]'::jsonb, 2, 'One unit of platelet concentrate is generally expected to raise the platelet count by roughly 5,000-10,000/mm3 in an average adult.', 'NAP 432 · General Anaesthesia II'),
(3, 92, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'In a patient with sickle cell disease, the anaesthetic team must avoid:', '["Hypoxia, dehydration, hypothermia and acidosis", "Warming blankets", "Giving IV fluids and oxygen, because they trigger sickling crises", "Oxygen supplementation"]'::jsonb, 0, 'These trigger sickling and crises.', 'NAP 432 · General Anaesthesia II'),
(3, 93, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Which anaesthetic agent can raise intracranial pressure?', '["Thiopentone sodium", "Lignocaine", "Sevoflurane", "Propofol"]'::jsonb, 2, 'Volatile agents such as sevoflurane are cerebral vasodilators and can raise intracranial pressure. Propofol, thiopentone and lignocaine lower it.', 'NAP 432 · General Anaesthesia II'),
(3, 94, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A postoperative patient has persistent bleeding at the surgical site. What should be the nurse''s first action?', '["Administer pain medication", "Perform a dressing change", "Notify the healthcare provider", "Apply pressure and elevate the limb"]'::jsonb, 3, 'Direct pressure and limb elevation are first-line measures to control active bleeding at a surgical site while further help is obtained.', 'NAP 432 · General Anaesthesia II'),
(3, 95, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The most suitable in anaesthesia for geriatric patient is', '["General anaesthesia is better than regional in lower part of the body", "The drugs is not calculated by mg /body weight", "Always give doses at low level", "Local is not indicated"]'::jsonb, 2, 'Elderly patients have reduced organ reserve and drug clearance, so anaesthetic doses are generally reduced and titrated carefully.', 'NAP 432 · General Anaesthesia II'),
(3, 96, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The nurse assesses epidural block height in PACU by testing sensation to:', '["A loud noise close to each ear and on both sides of the neck", "Cold, such as ice or ethyl chloride spray", "Light touch on the face and neck", "A bright light shone into the eyes"]'::jsonb, 1, 'Record the level and compare both sides.', 'NAP 432 · General Anaesthesia II'),
(3, 97, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Each PACU bay should have, as a minimum:', '["A ventilator and a dialysis machine in every bay", "Only a manual blood pressure cuff and stethoscope", "Only a bed, a chair and a call bell for the patient", "Oxygen, suction, a self-inflating bag and monitors"]'::jsonb, 3, 'Emergency drugs and a defibrillator must be immediately available.', 'NAP 432 · General Anaesthesia II'),
(3, 98, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Which IV induction agent is most suitable for day-case surgery?', '["Morphine", "Propofol", "Ketamine", "Diazepam"]'::jsonb, 1, 'Propofol suits day-case surgery: rapid, clear-headed recovery with little hangover and anti-emetic properties.', 'NAP 432 · General Anaesthesia II'),
(3, 99, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Paracetamol IV for an adult over 50 kg after surgery is usually given at:', '["10 g every 2 hours (no maximum)", "1 g every 6 hours (max 4 g a day)", "100 mg once daily (maximum 100 mg in 24 hours)", "5 g as a single dose, then none"]'::jsonb, 1, 'Reduce dose in low weight or liver disease.', 'NAP 432 · General Anaesthesia II'),
(3, 100, 'Anaesthesia Nursing Mock — Day 7 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The mean arterial pressure of a blood pressure of 160 / 80 is:', '["110 mmHg", "100 mmHg", "90 mmHg", "120 mmHg"]'::jsonb, 0, 'Mean arterial pressure ≈ DBP + 1/3(SBP-DBP) = 80 + 1/3(160-80) ≈ 107mmHg, closest to the 110mmHg option among the choices given.', 'NAP 432 · General Anaesthesia II');
